import MESSAGES from "@uploadedApps/messages";
import { isEmpty, get } from "lodash";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";
import {
    APP_INSPECT_STATUSES,
    FINAL_STATUSES,
    STATUSES,
} from "./PackagesTable.constants";

const STATUS_MESSAGES = MESSAGES.PACKAGES_TABLE.STATUSES;

export const isVetting = (status) => status === STATUSES.vetting;

export const isStatusFailed = (status) =>
    status === STATUS_MESSAGES[STATUSES.failed] ||
    status === STATUS_MESSAGES[STATUSES.unknown];

export const getStatus = (status) => STATUS_MESSAGES[status] || "";

export const isStatusAvailable = (status) => FINAL_STATUSES.has(status);

export const getStatusMessageForNoah = (app) => {
    const isPrivateAppGlobal = GlobalContextStore.get(KEYS.privateAppGlobal);
    if (isEmpty(app)) {
        return "";
    }
    if (app.isFetchingStatus) {
        return isPrivateAppGlobal
            ? MESSAGES.PACKAGES_TABLE.VALIDATING
            : MESSAGES.PACKAGES_TABLE.VETTING;
    }
    const { status, raw } = app;
    if (
        status === APP_INSPECT_STATUSES.SUCCESS &&
        get(raw, "content.app_installed")
    ) {
        return MESSAGES.PACKAGES_TABLE.INSTALLED;
    }
    return (
        MESSAGES.PACKAGES_TABLE.APP_INSPECT_STATUSES[status] ||
        `status - ${status}`
    );
};
