import { get } from "lodash";
import { prefixDataTestIds } from "@shared/lib/utils";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";

import MESSAGES from "./messages";

export function isSHC(json) {
    return !!get(json, "entry[0].content.SHCDeployer");
}

export function getAppName(pkg = {}) {
    if (!pkg || !pkg.content) {
        return "";
    }
    if (pkg.content["@app"] && pkg.content["@app"].label) {
        // If the @app key is available, use the label attr
        return pkg.content["@app"].label;
    }
    // Default to using the uploaded filename when @app.label is unavailable
    return pkg.content.uploadedFile || "";
}

export const normalizeDataTestIds = (compName, testIds = {}) => {
    return prefixDataTestIds({
        remoteAppName: "UploadedApps",
        compName,
        testIds,
    });
};

export const getInstanceType = () => GlobalContextStore.get(KEYS.instanceType);

export const extractErrorMessage = (errorCode, defaultErrorMessage = "") => {
    if (!errorCode) {
        return MESSAGES.ERRORS.GENERIC_ERROR_MESSAGE;
    }

    if (errorCode in MESSAGES.ERRORS) {
        return MESSAGES.ERRORS[errorCode];
    }
    return defaultErrorMessage || MESSAGES.ERRORS.GENERIC_ERROR_MESSAGE;
};
