import { createRESTURL, createURL } from "@splunk/splunk-utils/url";
import {
    defaultFetchInit,
    handleResponse,
    handleError,
} from "@splunk/splunk-utils/fetch";
import { _ } from "@splunk/ui-utils/i18n";
import querystring from "querystring";
import { get } from "lodash";

const APPS_LOCAL_PATH = "/services/apps/local";

export const getTaskEndpoint = (taskId) =>
    createRESTURL(`/services/dmc/tasks/${taskId}`);

export const LAST_DEPLOY = createRESTURL("dmc/deploy");

export function getUser(username) {
    const qs = querystring.encode({ output_mode: "json" });
    const user = encodeURIComponent(username);
    return fetch(createRESTURL(`authentication/users/${user}?${qs}`), {
        ...defaultFetchInit,
    })
        .then(handleResponse(200))
        .catch(handleError(_(`Unable to fetch user. Username - ${username}`)));
}

export function getDMCSettings() {
    const data = { output_mode: "json" };
    return fetch(
        createRESTURL(`dmc-conf/settings/settings?${querystring.encode(data)}`),
        {
            ...defaultFetchInit,
        }
    )
        .then(handleResponse(200))
        .catch(handleError(_("Unable to fetch DMC settings.")));
}

export function getTopology() {
    return fetch(createRESTURL("dmc/topologies"), {
        ...defaultFetchInit,
    })
        .then(handleResponse(200))
        .catch(handleError(_(`Unable to fetch topologies.`)));
}

export function fetchMaxUploadSize() {
    return fetch(createRESTURL("properties/web/settings/max_upload_size"), {
        ...defaultFetchInit,
    })
        .then(handleResponse(200))
        .then((size) => size * 1024 * 1024)
        .catch(() => {
            // the default value in backend is 500 MB
            return 500 * 1024 * 1024;
        });
}

export function getServerInfo() {
    return fetch(createRESTURL("server/info/server-info?output_mode=json"), {
        ...defaultFetchInit,
    })
        .then(handleResponse(200))
        .catch(handleError(_("Unable to get server info")));
}

export function getRoles() {
    const data = { count: 0, output_mode: "json" };
    return fetch(
        createRESTURL(`authorization/roles?${querystring.encode(data)}`),
        {
            ...defaultFetchInit,
        }
    )
        .then(handleResponse(200))
        .catch(handleError(_(`Unable to fetch roles.`)));
}

export function getLastDeployTask() {
    return fetch(LAST_DEPLOY, {
        ...defaultFetchInit,
        method: "GET",
    })
        .then(handleResponse(200))
        .catch(handleError(_(`Unable to fetch last deploy task.`)));
}

export function getTaskStatus(taskId) {
    return fetch(getTaskEndpoint(taskId), {
        ...defaultFetchInit,
        method: "GET",
    })
        .then(handleResponse(200))
        .catch(handleError(_(`Unable to fetch task status. ID - ${taskId}`)));
}

export const createSetUpLink = (appName) => {
    return createURL(`manager/${appName}/apps/local/${appName}/setup`, {
        action: "edit",
    });
};

export const createSetUpViewLink = (appName, setupView) => {
    return createURL(`app/${appName}/${setupView}`, {
        action: "edit",
    });
};

export function getLocalAppDetails(appId) {
    return fetch(
        createRESTURL(`/services/apps/local/${appId}?output_mode=json`),
        {
            ...defaultFetchInit,
        }
    )
        .then(handleResponse(200))
        .then((response) => get(response, "entry[0]"))
        .catch(handleError(_("Unable to fetch app details.")));
}

export function enableLocalApp(enableLink) {
    const fetchInit = {
        ...defaultFetchInit,
        method: "POST",
    };
    return fetch(createRESTURL(`${enableLink}?output_mode=json`), fetchInit)
        .then(handleResponse(200))
        .catch(handleError(_(`Failed to enable app.`)));
}

export function getTargetedAppInstallationStatus() {
    return fetch(
        createRESTURL(
            "/services/app_management/features/targeted_app_installation?output_mode=json"
        ),
        {
            ...defaultFetchInit,
        }
    )
        .then(handleResponse(200))
        .then((response) => Boolean(response.enabled))
        .catch(() => false);
}

export function updateDMCApp(updateLink, data, appName) {
    const { headers } = defaultFetchInit;
    const fetchInit = {
        ...defaultFetchInit,
        method: "POST",
        body: JSON.stringify(data),
        headers: {
            ...headers,
            "Content-Type": "application/json",
        },
    };
    return fetch(createRESTURL(updateLink), fetchInit)
        .then(handleResponse(200))
        .catch(handleError(_(`Failed to update app. ID - ${appName}`)));
}

export function updateLocalApp(data, appName) {
    const headers = {
        ...defaultFetchInit.headers,
        "Content-Type": "application/x-www-form-urlencoded",
    };

    const encodedData = querystring.encode(data);

    const fetchInit = {
        ...defaultFetchInit,
        method: "POST",
        body: encodedData,
        headers,
    };
    return fetch(
        createRESTURL(`${APPS_LOCAL_PATH}/${appName}/update?output_mode=json`),
        fetchInit
    )
        .then(handleResponse(200))
        .catch(handleError(_(`Failed to update app. ID - ${appName}`)));
}
