import PropTypes from "prop-types";
import React, { Component } from "react";
import Button from "@splunk/react-ui/Button";
import Message from "@shared/components/Message";
import Modal from "@splunk/react-ui/Modal";
import P from "@splunk/react-ui/Paragraph";
import Text from "@splunk/react-ui/Text";
import { renderContentInNewWindow } from "@shared/lib/utils";
import ALL_MESSAGES from "@uploadedApps/messages";
import {
    fetchAppVettingStatus,
    fetchReportForNoah,
    loginToNoah,
} from "@uploadedApps/services/APIService";
import { get } from "lodash";

import { extractErrorMessage } from "@uploadedApps/utils";
import TEST_IDS from "./CheckAppStatus.testids";
import {
    ACTION_AFTER_AUTH,
    APP_INSPECT_STATUSES,
} from "../PackagesTable.constants";

const MESSAGES = ALL_MESSAGES.CHECK_STATUS_MODAL;
const APP_VETTING_MESSAGE = {
    [APP_INSPECT_STATUSES.SUCCESS]: MESSAGES.APP_APPROVED_MESSAGE_PART1,
    [APP_INSPECT_STATUSES.PROCESSING]: MESSAGES.APP_VETTING_IN_PROGRESS_MESSAGE,
    [APP_INSPECT_STATUSES.FAILURE]: MESSAGES.APP_REJECTED_MESSAGE,
};

export default class CheckAppStatus extends Component {
    getInitialState = () => ({
        password: "",
        username: "",
        isLoading: false,
        isStatusRetrieved: false,
        error: null,
        appVettingStatus: "",
    });

    state = this.getInitialState();

    get isFetchReportView() {
        return (
            this.props.performActionAfterAuth === ACTION_AFTER_AUTH.FETCH_REPORT
        );
    }

    handleUsernameText = (e, { value }) => {
        this.setState({ username: value });
    };

    handlePasswordText = (e, { value }) => {
        this.setState({ password: value });
    };

    handleCheckStatusBtnClick = async () => {
        this.setState({
            isLoading: true,
            error: null,
            isStatusRetrieved: false,
        });
        const { username, password } = this.state;
        try {
            const authToken = await loginToNoah({ username, password });
            let updatedApp = null;
            if (this.isFetchReportView) {
                await this.fetchAppReport({ authToken });
            } else {
                updatedApp = await this.fetchAppStatus(authToken);
            }
            this.setState(
                {
                    isLoading: false,
                    isStatusRetrieved: true,
                    appVettingStatus: updatedApp ? updatedApp.status : "",
                },
                () => {
                    this.props.onSuccess({
                        authToken,
                        updatedApp,
                    });
                }
            );
        } catch (error) {
            this.setState({
                error,
                isLoading: false,
            });
        }
    };

    fetchAppStatus = (authToken) =>
        fetchAppVettingStatus({
            authToken,
            appSHA: get(this.props, "app.id"),
        });

    fetchAppReport = async ({ authToken }) => {
        const response = await fetchReportForNoah({
            appSHA: get(this.props, "app.id"),
            authToken,
        });
        if (response) {
            renderContentInNewWindow(response);
        }
    };

    handleCancelBtnClick = () => {
        this.setState(
            {
                ...this.getInitialState(),
            },
            this.props.handleClose
        );
    };

    isCheckStatusBtnDisabled = () => {
        return (
            this.state.isLoading ||
            !this.state.username.length ||
            !this.state.password.length
        );
    };

    getCancelBtnLabel = () => {
        return !this.state.isStatusRetrieved
            ? ALL_MESSAGES.COMMON.CANCEL
            : ALL_MESSAGES.COMMON.CLOSE;
    };

    getCancelBtnAppearance = () => {
        return !this.state.isStatusRetrieved ? "default" : "primary";
    };

    getBodyContent = () => {
        if (this.state.isStatusRetrieved) {
            if (this.isFetchReportView) {
                return MESSAGES.FETCHING_REPORT;
            }
            const { appVettingStatus } = this.state;
            return appVettingStatus && appVettingStatus in APP_VETTING_MESSAGE
                ? APP_VETTING_MESSAGE[appVettingStatus]
                : MESSAGES.GENERIC_APP_STATUS_MESSAGE(appVettingStatus);
        }

        return (
            <>
                {this.state.error && (
                    <Message type="error">
                        {extractErrorMessage(this.state.error)}
                    </Message>
                )}
                <P>
                    {MESSAGES.MESSAGE1({
                        retrieveWord: this.isFetchReportView
                            ? "fetch"
                            : "check",
                        subject: this.isFetchReportView ? "report" : "status",
                    })}
                </P>
                <br />
                <Text
                    autoFocus
                    data-test-name={TEST_IDS.USERNAME_INPUT}
                    onChange={this.handleUsernameText}
                    name="username"
                    placeholder="Username"
                    style={{ width: "300px", marginBottom: "10px" }}
                    value={this.state.username}
                />
                <Text
                    data-test-name={TEST_IDS.PASSWORD_INPUT}
                    onChange={this.handlePasswordText}
                    name="password"
                    placeholder="Password"
                    style={{ width: "300px" }}
                    type="password"
                    value={this.state.password}
                />
            </>
        );
    };

    render() {
        return (
            <Modal
                open={this.props.open}
                style={{ width: "690px" }}
                data-test-name={TEST_IDS.MODAL}
            >
                <Modal.Header
                    onRequestClose={this.handleCancelBtnClick}
                    title={
                        this.isFetchReportView
                            ? MESSAGES.MODAL_TITLE_VIEW_REPORT
                            : MESSAGES.MODAL_TITLE_CHECK_STATUS
                    }
                />
                <Modal.Body>{this.getBodyContent()}</Modal.Body>
                <Modal.Footer>
                    <Button
                        data-test-name={TEST_IDS.CLOSE_BTN}
                        label={this.getCancelBtnLabel()}
                        onClick={this.handleCancelBtnClick}
                        appearance={this.getCancelBtnAppearance()}
                    />
                    {!this.state.isStatusRetrieved && (
                        <Button
                            appearance="primary"
                            data-test-name={TEST_IDS.CHECK_STATUS_BTN}
                            disabled={this.isCheckStatusBtnDisabled()}
                            label={
                                this.isFetchReportView
                                    ? MESSAGES.FETCH_REPORT_BTN_LABEL
                                    : MESSAGES.CHECK_STATUS_BTN_LABEL
                            }
                            onClick={this.handleCheckStatusBtnClick}
                            value={{
                                username: this.state.username,
                                password: this.state.password,
                            }}
                        />
                    )}
                </Modal.Footer>
            </Modal>
        );
    }
}

CheckAppStatus.propTypes = {
    handleClose: PropTypes.func.isRequired,
    open: PropTypes.bool.isRequired,
    onSuccess: PropTypes.func,
    // eslint-disable-next-line react/no-unused-prop-types
    app: PropTypes.any,
    performActionAfterAuth: PropTypes.oneOf(["CHECK_STATUS", "FETCH_REPORT"]),
};
