import React, { useState, useCallback, useMemo } from "react";
import PropTypes from "prop-types";
import Button from "@splunk/react-ui/Button";
import Modal from "@splunk/react-ui/Modal";
import Link from "@splunk/react-ui/Link";
import Message from "@shared/components/Message";
import { get } from "lodash";

import { SPLUNK_DEV_DOCS_URL } from "@uploadedApps/constants";
import MESSAGES from "@uploadedApps/messages";
import { getInstanceType } from "@uploadedApps/utils";
import { createRESTURL } from "@splunk/splunk-utils/url";
import { INSTANCE_TYPES } from "@shared/constants";
import { renderContentInNewWindow } from "@shared/lib/utils";
import { fetchReportForNoah } from "@uploadedApps/services/APIService";
import TEST_IDS from "./VettingErrorModal.testids";

const VettingErrorModal = ({
    app,
    authToken,
    vettingErrorCount,
    handleClose,
    open,
}) => {
    const isDMC = getInstanceType() === INSTANCE_TYPES.DMC;
    const [isFetchingReport, setIsFetchingReport] = useState(false);

    const fetchAppReport = useCallback(async () => {
        setIsFetchingReport(true);
        const { id: appId } = app;
        try {
            const response = await fetchReportForNoah({
                appSHA: appId,
                authToken: authToken.value,
            });
            if (response) {
                renderContentInNewWindow(response);
            }
            setIsFetchingReport(false);
        } catch (error) {
            setIsFetchingReport(false);
        }
    }, [app, authToken]);

    const viewReportLink = useMemo(
        () => createRESTURL(get(app, "raw.links.report", "")),
        [app]
    );

    return (
        <div>
            <Modal data-test-name={TEST_IDS.MODAL} open={open}>
                <Modal.Header
                    title={MESSAGES.VETTING_ERROR_MODAL.MODAL_TITLE}
                    onRequestClose={handleClose}
                />
                <Modal.Body>
                    <Message type="error">
                        <p>
                            <strong>
                                {MESSAGES.VETTING_ERROR_MODAL.NO_OF_ISSUES(
                                    vettingErrorCount,
                                    isDMC
                                )}
                                &nbsp;
                            </strong>
                            {MESSAGES.VETTING_ERROR_MODAL.FOUND}
                        </p>
                        <p>
                            {MESSAGES.VETTING_ERROR_MODAL.MESSAGE1}
                            {isDMC ? (
                                <Link
                                    to={viewReportLink}
                                    openInNewContext
                                    data-test-name={
                                        TEST_IDS.DESCRIPTION_VIEW_REPORT_BTN
                                    }
                                >
                                    {MESSAGES.COMMON.REPORT}
                                </Link>
                            ) : (
                                <Link
                                    onClick={fetchAppReport}
                                    openInNewContext
                                    disabled={isFetchingReport}
                                    data-test-name={
                                        TEST_IDS.DESCRIPTION_VIEW_REPORT_BTN
                                    }
                                >
                                    {MESSAGES.COMMON.REPORT}
                                </Link>
                            )}
                            {MESSAGES.VETTING_ERROR_MODAL.MESSAGE2}
                            <Link to={SPLUNK_DEV_DOCS_URL} openInNewContext>
                                {
                                    MESSAGES.VETTING_ERROR_MODAL
                                        .SPLUNK_DEVELOPER_DOCS
                                }
                            </Link>
                        </p>
                    </Message>
                </Modal.Body>
                <Modal.Footer>
                    <Button
                        data-test-name={TEST_IDS.CANCEL_BTN}
                        onClick={handleClose}
                        label={MESSAGES.COMMON.CLOSE}
                    />
                    {isDMC ? (
                        <Button
                            appearance="primary"
                            to={viewReportLink}
                            openInNewContext
                            data-test-name={TEST_IDS.VIEW_REPORT_BTN}
                            label={MESSAGES.COMMON.VIEW_REPORT}
                        />
                    ) : (
                        <Button
                            disabled={isFetchingReport}
                            appearance="primary"
                            onClick={fetchAppReport}
                            data-test-name={TEST_IDS.VIEW_REPORT_BTN}
                            label={MESSAGES.COMMON.VIEW_REPORT}
                        />
                    )}
                </Modal.Footer>
            </Modal>
        </div>
    );
};
VettingErrorModal.propTypes = {
    open: PropTypes.bool.isRequired,
    handleClose: PropTypes.func.isRequired,
    vettingErrorCount: PropTypes.number.isRequired,
    app: PropTypes.any,
    authToken: PropTypes.shape({
        value: PropTypes.string.isRequired,
        expiry: PropTypes.number.isRequired,
    }),
};

export default VettingErrorModal;
