import React from "react";
import PropTypes from "prop-types";
import Modal from "@splunk/react-ui/Modal";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";

import MESSAGES from "@uploadedApps/messages";
import { getInstanceType } from "@uploadedApps/utils";
import { INSTANCE_TYPES } from "@shared/constants";
import TEST_IDS from "./VettingProgressModal.testids";

const VettingProgressModal = (props) => {
    const isPrivateAppGlobal = GlobalContextStore.get(KEYS.privateAppGlobal);
    const isNoah = getInstanceType() === INSTANCE_TYPES.NOAH;
    const headerProps = {
        title: MESSAGES.VETTING_PROGRESS_MODAL.MODAL_TITLE(isPrivateAppGlobal),
    };
    if (isNoah) {
        headerProps.onRequestClose = props.handleClose;
    }
    return (
        <div>
            <Modal data-test-name={TEST_IDS.MODAL} open={props.open}>
                <Modal.Header {...headerProps} />
                <Modal.Body>
                    <div>
                        {isPrivateAppGlobal
                            ? MESSAGES.VETTING_PROGRESS_MODAL.MODAL_BODY_VALIDATING(
                                  props.filename
                              )
                            : MESSAGES.VETTING_PROGRESS_MODAL.MODAL_BODY_VETTING(
                                  props.filename,
                                  isNoah
                              )}
                    </div>
                </Modal.Body>
            </Modal>
        </div>
    );
};

VettingProgressModal.propTypes = {
    handleClose: PropTypes.func.isRequired,
    filename: PropTypes.string.isRequired,
    open: PropTypes.bool.isRequired,
};

export default VettingProgressModal;
