import PropTypes from "prop-types";
import React, { useState, useCallback, useEffect } from "react";
import { get } from "lodash";
import {
    getLocalAppDetails,
    enableLocalApp,
    createSetUpLink,
    createSetUpViewLink,
} from "@shared/services/APIService";
import AppActionModal, {
    APP_ACTION_MODAL_ACTIONS,
    APP_ACTION_MODAL_STATUSES,
} from "@shared/components/AppActionModal";

const CheckInstallationStatus = ({ onClose, isOpen, appId, onAppEnabled }) => {
    const [modalConfig, setModalConfig] = useState();

    const setModalIsWorking = useCallback(() => {
        setModalConfig((prev) => ({ ...prev, isWorking: true }));
    }, []);

    const setModalError = useCallback(() => {
        setModalConfig((prev) => ({
            ...prev,
            isWorking: false,
            status: APP_ACTION_MODAL_STATUSES.error,
        }));
    }, []);

    const setModalInfo = useCallback(
        ({ app, action, handleCancel, handleFinish, handleConfirm }) => {
            setModalConfig((prev) => ({
                ...prev,
                isOpen: true,
                isWorking: false,
                appName: get(app, "content.label", app.name),
                status: APP_ACTION_MODAL_STATUSES.info,
                action,
                handleCancel,
                handleFinish,
                handleConfirm,
            }));
        },
        []
    );

    const setModalSuccess = useCallback(() => {
        setModalConfig((prev) => ({
            ...prev,
            isWorking: false,
            status: APP_ACTION_MODAL_STATUSES.success,
        }));
    }, []);

    const handleAsyncFunction = useCallback(
        async (callback) => {
            setModalIsWorking();
            try {
                await callback();
            } catch (e) {
                setModalError();
            }
        },
        [setModalError, setModalIsWorking]
    );

    const handleEnableApp = useCallback(
        async (enableLink) => {
            await handleAsyncFunction(async () => {
                await enableLocalApp(enableLink);
                setModalSuccess();
                onAppEnabled?.();
            });
        },
        [handleAsyncFunction, onAppEnabled, setModalSuccess]
    );

    const handleSetupApp = useCallback(
        (setupView) => {
            let setupViewUrl = createSetUpLink(appId);
            if (setupView.length > 0) {
                setupViewUrl = createSetUpViewLink(appId, setupView);
            }

            window.location.href = setupViewUrl;
        },
        [appId]
    );

    const handleOnClose = useCallback(() => {
        setModalConfig({});
        onClose();
    }, [onClose]);

    const checkAppInstallationStatus = useCallback(
        async ({ skipEnableCheck = false } = {}) => {
            try {
                const appDetails = await getLocalAppDetails(appId);
                const isDisabled = get(appDetails, "content.disabled");
                const appEnableLink = get(appDetails, "links.enable");
                const isConfigured = get(appDetails, "content.configured");
                const hasSetupLink = !!get(appDetails, "links.setup");

                if (!skipEnableCheck && isDisabled && !!appEnableLink) {
                    const checkInstallationAndSkipEnable = () =>
                        checkAppInstallationStatus({
                            skipEnableCheck: true,
                        });

                    setModalInfo({
                        app: appDetails,
                        handleCancel: checkInstallationAndSkipEnable,
                        handleFinish: checkInstallationAndSkipEnable,
                        handleConfirm: () => handleEnableApp(appEnableLink),
                        action: APP_ACTION_MODAL_ACTIONS.enable,
                    });
                    return;
                }

                if (!isConfigured && hasSetupLink) {
                    const setupView = get(appDetails, "content.setup_view", "");
                    setModalInfo({
                        app: appDetails,
                        handleCancel: handleOnClose,
                        handleConfirm: () => handleSetupApp(setupView),
                        action: APP_ACTION_MODAL_ACTIONS.setup,
                    });

                    return;
                }
                handleOnClose();
            } catch (_) {
                // is appId returns 404 it the checks
                handleOnClose();
            }
        },
        [appId, handleEnableApp, handleOnClose, handleSetupApp, setModalInfo]
    );

    useEffect(() => {
        if (appId && isOpen) {
            checkAppInstallationStatus();
        }
    }, [appId, checkAppInstallationStatus, isOpen]);

    if (!modalConfig?.isOpen) {
        return null;
    }

    return (
        <AppActionModal
            action={modalConfig.action}
            status={modalConfig.status}
            appName={modalConfig.appName}
            onClose={modalConfig.handleCancel}
            onConfirm={modalConfig.handleConfirm}
            isWorking={modalConfig.isWorking}
            onFinish={modalConfig.handleFinish}
            open={modalConfig.isOpen}
            errorMessage={modalConfig.errorMessage}
        />
    );
};

CheckInstallationStatus.propTypes = {
    isOpen: PropTypes.bool.isRequired,
    onClose: PropTypes.func.isRequired,
    appId: PropTypes.string.isRequired,
    onAppEnabled: PropTypes.func,
};

export default CheckInstallationStatus;
