import PollSplunkEndpoint from "@shared/services/Polling";
import { STATUSES as PACKAGE_STATUS } from "@uploadedApps/UploadedAppsPage/PackagesTable/PackagesTable.constants";
import { PACKAGES_COLLECTION_PATH } from "./APIService";

let packagesPoll;
let latestPollPromise;

export const defaultValidationFn = (resp) => {
    // If there no packages or if there are not packages in vetting state, stop polling
    return (
        resp.entry.length === 0 ||
        !resp.entry.some((pkg) => pkg.content.status === PACKAGE_STATUS.vetting)
    );
};

const setupPackagesPoll = (pollingOptions) => {
    // poll packages endpoint to until there are no packages in the vetting state
    const pkgPollingOpt = {
        timeout: 15 * 60 * 1000, // 15 min
        url: PACKAGES_COLLECTION_PATH,
        validationFn: defaultValidationFn,
        ...pollingOptions,
    };
    return new PollSplunkEndpoint(pkgPollingOpt);
};

class PollPackagesCollectionService {
    start = (pollingOptions = {}) => {
        if (!packagesPoll) {
            packagesPoll = setupPackagesPoll(pollingOptions);
        }
        if (packagesPoll.isPolling) {
            return latestPollPromise;
        }
        latestPollPromise = packagesPoll.startPolling();
        return latestPollPromise;
    };

    stop = () => {
        if (!packagesPoll || !packagesPoll.isPolling) {
            return;
        }
        packagesPoll.stopPolling();
    };
}

const PollPackagesCollection = new PollPackagesCollectionService();
export default PollPackagesCollection;
