import React from "react";
import PropTypes from "prop-types";
import Message from "@shared/components/Message";
import SingleFileUpload, {
    STATUS as FILE_UPLOAD_STATUS,
} from "@shared/components/SingleFileUpload";
import Button from "@splunk/react-ui/Button";
import Modal from "@splunk/react-ui/Modal";
import { uploadPackage } from "@uploadedApps/services/APIService";
import { MODAL_STATUS } from "@uploadedApps/constants";
import Link from "@splunk/react-ui/Link";
import ERRORS from "@uploadedApps/errors.js";
import MESSAGES from "@uploadedApps/messages";
import { MESSAGES as COMMON_MESSAGES } from "@shared/messages";
import { extractErrorMessage, getInstanceType } from "@uploadedApps/utils";
import { sendUploadAppSaveEvent } from "@shared/services/Telemetry";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";
import P from "@splunk/react-ui/Paragraph";

import { INSTANCE_TYPES } from "@shared/constants";
import TEST_IDS from "./UploadModal.testids";

class UploadModal extends React.Component {
    constructor(props) {
        super(props);
        this.state = this.getInitialStateConfig();
    }

    getInitialStateConfig = () => ({
        isUploadingToServer: false,
        file: null,
        error: null,
        modalStatus: MODAL_STATUS.INITIAL,
    });

    handleFileUploadChange = ({ status, file }) => {
        if (
            status === FILE_UPLOAD_STATUS.DONE ||
            status === FILE_UPLOAD_STATUS.EMPTY
        ) {
            this.setState({
                file,
                error: null,
            });
        }
    };

    handleUploadFile = async () => {
        this.setState({
            isUploadingToServer: true,
            error: null,
        });

        try {
            const { appUniqueId } = await uploadPackage(
                this.state.file,
                this.props.authToken.value
            );
            this.setState(
                {
                    isUploadingToServer: false,
                    modalStatus: MODAL_STATUS.SUCCESS,
                },
                () => {
                    this.props.onSuccess({
                        appUniqueId,
                        authToken: this.props.authToken,
                        fileName: this.state.file.name,
                    });
                }
            );
        } catch (error) {
            this.setState({
                error,
                isUploadingToServer: false,
                modalStatus: MODAL_STATUS.ERROR,
            });
        }
        sendUploadAppSaveEvent();
    };

    handleModalClose = () => {
        this.setState(
            {
                ...this.getInitialStateConfig(),
            },
            this.props.handleClose
        );
    };

    buildUploadErrorMsg = (errorCode, fileName) => {
        // Build a more precise error message for Noah dupe app
        if (
            errorCode === ERRORS.APP_WITH_SHA_ALREADY_EXISTS &&
            getInstanceType() === INSTANCE_TYPES.NOAH
        ) {
            return (
                <div>
                    <div>
                        {
                            MESSAGES.ERRORS
                                .NOAH_APP_WITH_SHA_ALREADY_EXISTS_PREFIX
                        }
                    </div>
                    <div>
                        {MESSAGES.ERRORS.NOAH_APP_WITH_SHA_ALREADY_EXISTS_BODY(
                            fileName
                        )}
                    </div>
                </div>
            );
        }

        // Otherwise return general error message
        return extractErrorMessage(errorCode);
    };

    render() {
        const { file, isUploadingToServer, error, modalStatus } = this.state;
        const isModalStatusNotSuccess = modalStatus !== MODAL_STATUS.SUCCESS;
        const maxFileSize = GlobalContextStore.get(KEYS.maxFileSizeUpload);

        return (
            <Modal
                open={this.props.open}
                style={{ width: "690px" }}
                data-test-name={TEST_IDS.MODAL}
            >
                <Modal.Header
                    onRequestClose={this.handleModalClose}
                    title={MESSAGES.UPLOAD_MODAL.MODAL_TITLE}
                />
                <Modal.Body>
                    {error && (
                        <Message type="error">
                            {this.buildUploadErrorMsg(error, file?.name)}
                        </Message>
                    )}
                    {modalStatus === MODAL_STATUS.SUCCESS ? (
                        <Message type="success">
                            {MESSAGES.UPLOAD_MODAL.SUCCESSFUL_UPLOAD_MESSAGE(
                                file.name
                            )}
                        </Message>
                    ) : (
                        <>
                            <div style={{ width: "410px" }}>
                                <p>
                                    {MESSAGES.UPLOAD_MODAL.SUPPORTED_FILE_TYPES}
                                </p>
                                <SingleFileUpload
                                    onChange={this.handleFileUploadChange}
                                    maxFileSize={maxFileSize}
                                    data-test-name={TEST_IDS.FILE_UPLOAD}
                                />
                            </div>

                            <br />
                            <P>{MESSAGES.UPLOAD_MESSAGE}</P>

                            <P>
                                {COMMON_MESSAGES.ACKNOWLEDGE_TEXT}
                                <Link
                                    openInNewContext
                                    to="https://www.splunk.com/en_us/legal/terms/terms-of-use.html"
                                    data-test-name={TEST_IDS.TERMS_LINK}
                                >
                                    {COMMON_MESSAGES.TERMS_LINK}
                                </Link>
                            </P>
                        </>
                    )}
                </Modal.Body>
                <Modal.Footer>
                    <Button
                        appearance={
                            isModalStatusNotSuccess ? "secondary" : "primary"
                        }
                        data-test-name={TEST_IDS.CANCEL_BTN}
                        label={MESSAGES.COMMON.CLOSE}
                        onClick={this.handleModalClose}
                    />
                    {isModalStatusNotSuccess && (
                        <Button
                            appearance="primary"
                            data-test-name={TEST_IDS.UPLOAD_BTN}
                            disabled={!file || isUploadingToServer}
                            label={
                                !isUploadingToServer
                                    ? MESSAGES.COMMON.UPLOAD
                                    : MESSAGES.COMMON.UPLOADING
                            }
                            onClick={this.handleUploadFile}
                        />
                    )}
                </Modal.Footer>
            </Modal>
        );
    }
}

UploadModal.propTypes = {
    handleClose: PropTypes.func.isRequired,
    open: PropTypes.bool.isRequired,
    authToken: PropTypes.shape({
        value: PropTypes.string.isRequired,
        expiry: PropTypes.number.isRequired,
    }),
    onSuccess: PropTypes.func,
};
export default UploadModal;
