import React, { useMemo } from "react";
import PropTypes from "prop-types";
import Modal from "@splunk/react-ui/Modal";
import Button from "@splunk/react-ui/Button";
import Message from "@shared/components/Message";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";
import { boldText } from "@shared/lib/renderUtils";
import { INSTANCE_TYPES } from "@shared/constants";
import {
    APP_ACTION_MODAL_ACTIONS,
    APP_ACTION_MODAL_STATUSES,
    APP_ACTION_MODAL_STATES,
    statusToStateMapper,
    isFooterVisibleByState,
} from "./utils";
import MESSAGES from "./AppActionModal.messages";
import TEST_IDS from "./AppActionModal.testids";

const getBodyMsg = (
    bodyMessage,
    { appName, supportedDeployments = [], errorMessage }
) => {
    let shcMsg = "";
    // We only need this for DMC and NOT Noah
    const isSHC = GlobalContextStore.get(KEYS.isSHC);
    const isDMC =
        GlobalContextStore.get(KEYS.instanceType) === INSTANCE_TYPES.DMC;
    if (isDMC && isSHC) {
        const SHCUnsupported = !supportedDeployments.some((item) =>
            ["_search_head_clustering", "*"].includes(item)
        );

        if (SHCUnsupported) {
            shcMsg = MESSAGES.DMC.SHC_WARNING;
        }
    }

    const msg =
        typeof bodyMessage === "function"
            ? bodyMessage(appName, shcMsg, errorMessage)
            : bodyMessage;

    // Make app name bold
    return boldText(msg, appName);
};

const AppActionModal = ({
    action,
    appName,
    supportedDeployments,
    onClose,
    onConfirm,
    onFinish,
    isWorking,
    open,
    status,
    errorMessage,
}) => {
    const actionState = statusToStateMapper(status, isWorking);
    const messages = useMemo(() => MESSAGES[action][actionState], [
        action,
        actionState,
    ]);
    const hasSubmitAction = useMemo(
        () =>
            [
                APP_ACTION_MODAL_STATES.confirm,
                APP_ACTION_MODAL_STATES.error,
            ].includes(actionState) && messages?.CONFIRM_BTN,
        [actionState, messages]
    );
    const handleCancel = useMemo(
        () =>
            actionState === APP_ACTION_MODAL_STATES.success && onFinish
                ? onFinish
                : onClose,
        [actionState, onClose, onFinish]
    );

    if (!messages) {
        return <></>;
    }

    return (
        <Modal data-test-name={TEST_IDS.MODAL} open={open}>
            <Modal.Header
                data-test-name={TEST_IDS.TITLE}
                onRequestClose={onClose}
                title={messages.TITLE}
            />
            <Modal.Body data-test-name={TEST_IDS.BODY}>
                <Message type={status}>
                    {getBodyMsg(messages.BODY, {
                        appName,
                        supportedDeployments,
                        errorMessage,
                    })}
                </Message>
            </Modal.Body>

            {isFooterVisibleByState(actionState) && (
                <Modal.Footer>
                    <Button
                        data-test-name={TEST_IDS.CLOSE_BTN}
                        label={messages.CLOSE_BTN}
                        disabled={isWorking}
                        onClick={handleCancel}
                    />
                    {hasSubmitAction && (
                        <Button
                            appearance="primary"
                            data-test-name={TEST_IDS.CONFIRM_BTN}
                            disabled={isWorking}
                            label={messages.CONFIRM_BTN}
                            onClick={onConfirm}
                        />
                    )}
                </Modal.Footer>
            )}
        </Modal>
    );
};

AppActionModal.propTypes = {
    action: PropTypes.oneOf(Object.values(APP_ACTION_MODAL_ACTIONS)).isRequired,
    status: PropTypes.oneOf(Object.values(APP_ACTION_MODAL_STATUSES))
        .isRequired,
    appName: PropTypes.string.isRequired,
    onClose: PropTypes.func.isRequired,
    isWorking: PropTypes.bool.isRequired,
    open: PropTypes.bool.isRequired,
    // This is only when splunk is SHC
    supportedDeployments: PropTypes.arrayOf(PropTypes.string),
    onConfirm: PropTypes.func,
    onFinish: PropTypes.func,
    errorMessage: PropTypes.string,
};
export default AppActionModal;
