export const convertToNearestSize = (bytes, precisionParam = 0) => {
    if (!bytes) {
        return "0 Bytes";
    }

    const block = 1024;
    const precision = precisionParam < 0 ? 0 : precisionParam;
    const sizes = ["Bytes", "KB", "MB", "GB", "TB", "PB"];
    const i = Math.floor(Math.log(bytes) / Math.log(block));

    return `${parseFloat((bytes / block ** i).toFixed(precision))} ${sizes[i]}`;
};

export const generateFileSizeLimitExceededError = (size) =>
    new Error(
        `Upload failed: Package is too large, must be less than ${convertToNearestSize(
            size
        )}`
    );
