import React from "react";
import MESSAGES from "@uploadedApps/messages";

export function getTitle(app) {
    let title;
    const { errors } = app;
    if (
        errors &&
        typeof errors[0].type === "string" &&
        errors[0].type === "AppUpload_DuplicateVersion"
    ) {
        title = MESSAGES.MORE_INFO_MODAL.MODAL_TITLE(
            MESSAGES.MORE_INFO_MODAL.APP_VALIDATION_REJECTED_TITLE
        );
    } else {
        // default title
        title = MESSAGES.MORE_INFO_MODAL.MODAL_TITLE(
            MESSAGES.MORE_INFO_MODAL.APP_VALIDATION_FAILED_TITLE
        );
    }
    return title;
}

export function getMessages(app) {
    const { errors, id } = app;
    let message;

    if (errors && typeof errors[0].type === "string") {
        if (errors[0].type === "AppUpload_DuplicateVersion") {
            message = [
                MESSAGES.MORE_INFO_MODAL.DUPLICATE_VERSION_ERROR_MESSAGE
                    .VALIDATION_FAILED,
                <ul key={id}>
                    <li key={id}>
                        <b>{errors[0].payload.app_label}</b>
                        {MESSAGES.MORE_INFO_MODAL.DUPLICATE_VERSION_ERROR_MESSAGE.ALREADY_UPLOADED(
                            errors[0].payload.app_version
                        )}
                    </li>
                </ul>,
                MESSAGES.MORE_INFO_MODAL.DUPLICATE_VERSION_ERROR_MESSAGE
                    .UNIQUE_VERSION,
            ];
        } else if (errors[0].type === "AppInstall_UnsupportedDeployment") {
            message = [
                MESSAGES.MORE_INFO_MODAL.APP_VALIDATION_UNSUPPORTED_DEPLOYMENT(
                    MESSAGES.MORE_INFO_MODAL.DEPLOYMENT_TYPES[
                        errors[0].payload.deployment
                    ]
                ),
            ];
        } else if (
            MESSAGES.MORE_INFO_MODAL.DMC_ERROR_MESSAGES[errors[0].type]
        ) {
            message = [
                MESSAGES.MORE_INFO_MODAL.DMC_ERROR_MESSAGES[errors[0].type],
            ];
        } else {
            message = [MESSAGES.MORE_INFO_MODAL.APP_VALIDATION_FAILED_TITLE];
        }
        const payloadMessage = errors[0].payload && errors[0].payload.message;
        if (payloadMessage) {
            message.push(
                <ul key={id}>
                    <li key={id}>{payloadMessage}</li>
                </ul>
            );
            if (errors[0].type === "AppUpload_InspectTimeOut") {
                message.push(
                    MESSAGES.MORE_INFO_MODAL
                        .APP_VALIDATION_TIMEOUT_MORE_INFO_MESSAGE
                );
            } else {
                message.push(
                    MESSAGES.MORE_INFO_MODAL.APP_VALIDATION_MORE_INFO_MESSAGE
                );
            }
        }
    }
    return message;
}
