/**
 * React Remote root
 * @param UploadedAppsRoot
 */
import React, { Component } from "react";
import { createRemote } from "@splunk/skinny-bundle-loader";
import SplunkThemeProvider from "@splunk/themes/SplunkThemeProvider";
import { get } from "lodash";
import Message from "@splunk/react-ui/Message";
import UploadedAppsPageContainer from "@uploadedApps/UploadedAppsPage";
import MESSAGES from "@uploadedApps/messages";
import { getInstanceType, isSHC } from "@uploadedApps/utils";
import { fetchMaxUploadSize } from "@shared/services/APIService";
import {
    getTopology,
    getUser,
    getPrivateAppGlobalFlag,
    fetchRequireAppInspectFlag,
    getPrivateAppGlobalFlagNoah,
    isDMCGetPackageEndpointAvailable,
} from "@uploadedApps/services/APIService";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";
import { SplunkOtelWrapper } from "@shared/lib/instrumentationRum";

import { INSTANCE_TYPES, CAPABILITIES } from "@shared/constants";

SplunkOtelWrapper();

const EDIT_CAPABILITY = {
    [INSTANCE_TYPES.DMC]: new Set([CAPABILITIES.DMC_DEPLOY_APPS]),
    [INSTANCE_TYPES.NOAH]: new Set([
        CAPABILITIES.INSTALL_APPS,
        CAPABILITIES.EDIT_LOCAL_APPS,
    ]),
};
/* global $C */
/* eslint no-undef: "error" */

export class UploadedAppsRoot extends Component {
    state = {
        error: "",
        // Set to true when bootstrap Promises are resolved
        bootstrapComplete: false,
    };

    async componentDidMount() {
        const topology = await this.fetchTopologyAndSetInstanceType();
        const instanceType = GlobalContextStore.get(KEYS.instanceType);

        const bootstrapPromiseArr = [
            getUser($C.USERNAME),
            fetchMaxUploadSize(),
        ];

        if (this.isDMC()) {
            bootstrapPromiseArr.push(getPrivateAppGlobalFlag());
            bootstrapPromiseArr.push(isDMCGetPackageEndpointAvailable());
        } else {
            bootstrapPromiseArr.push(getPrivateAppGlobalFlagNoah());
            bootstrapPromiseArr.push(fetchRequireAppInspectFlag());
        }

        try {
            const responses = await Promise.all(bootstrapPromiseArr);
            const userCapabilities = get(
                responses[0],
                "entry[0].content.capabilities",
                []
            );
            const editCapabilities = EDIT_CAPABILITY[instanceType] || new Set();
            const canEdit = userCapabilities.some((capability) =>
                editCapabilities.has(capability)
            );
            const globalData = {
                [KEYS.privateAppGlobal]: false,
                [KEYS.isSHC]: false,
                [KEYS.canEdit]: canEdit,
                [KEYS.requireAppInspect]: true,
                [KEYS.isDMCGetPackageAPIAvailable]: false,
                [KEYS.maxFileSizeUpload]: responses[1],
            };
            globalData[KEYS.privateAppGlobal] = !!responses[2];
            if (this.isDMC()) {
                globalData[KEYS.isSHC] = isSHC(topology);
                [, , globalData[KEYS.isDMCGetPackageAPIAvailable]] = responses;
            } else {
                globalData[KEYS.requireAppInspect] = !!responses[3];
            }
            GlobalContextStore.setMultiple(globalData);
            this.setState({
                bootstrapComplete: true,
            });
        } catch (error) {
            this.setState({ error });
        }
    }

    fetchTopologyAndSetInstanceType = async () => {
        let instanceType = INSTANCE_TYPES.DMC;
        let topology = {};
        try {
            topology = await getTopology();
        } catch (error) {
            instanceType = INSTANCE_TYPES.NOAH;
        }
        GlobalContextStore.set(KEYS.instanceType, instanceType);
        return topology;
    };

    isDMC = () => getInstanceType() === INSTANCE_TYPES.DMC;

    render() {
        let componentToRender;
        if (this.state.bootstrapComplete) {
            componentToRender = <UploadedAppsPageContainer {...this.props} />;
        } else if (this.state.error) {
            componentToRender = (
                <Message type="error">{this.state.error.message}</Message>
            );
        } else {
            componentToRender = <div>{MESSAGES.COMMON.LOADING}</div>;
        }
        return (
            <SplunkThemeProvider
                family="enterprise"
                colorScheme="light"
                density="comfortable"
            >
                {componentToRender}
            </SplunkThemeProvider>
        );
    }
}

/**
 *  UploadedAppsRemote is the remote component that gets exposed to the shell
 */
const UploadedAppsRemote = {
    root: UploadedAppsRoot,
};

// eslint-disable-next-line
let __webpack_public_path__;

export default createRemote(UploadedAppsRemote, (fnConfig) => {
    // eslint-disable-next-line
    __webpack_public_path__ = (() => {
        return `${fnConfig.remoteRoot}/`;
    })();
});
