import { _ } from "@splunk/ui-utils/i18n";
import React from "react";
import File from "@splunk/react-ui/File";
import PropTypes from "prop-types";
import Remove from "@splunk/react-icons/Remove";
import Message from "@shared/components/Message";

import { STATUS, MAX_FILE_SIZE_PROP_NAME } from "./SingleFileUpload.constants";
import { generateFileSizeLimitExceededError } from "./SingleFileUpload.helper";
import TEST_IDS from "./SingleFileUpload.testids";

const GENERIC_ERROR_MESSAGE = "Error uploading.";

export default class SingleFileUpload extends React.Component {
    state = {
        file: null,
        error: null,
        status: STATUS.EMPTY,
    };

    mostRecentUploadedFile = null;

    constructor(props) {
        super(props);
        this.initializeFileReader();
    }

    initializeFileReader = () => {
        this.fileReader = new FileReader();
        this.fileReader.onload = this.onUploadSuccess;
        this.fileReader.onerror = this.onUploadFailure;
        this.fileReader.onprogress = this.onUploadProgress;
    };

    triggerChange = () => {
        const { file, error, status } = this.state;
        this.props.onChange({
            file,
            error,
            status,
        });
    };

    onUploadSuccess = () => {
        if (
            MAX_FILE_SIZE_PROP_NAME in this.props &&
            this.mostRecentUploadedFile.size >
                this.props[MAX_FILE_SIZE_PROP_NAME]
        ) {
            this.updateStateOnFailure(
                generateFileSizeLimitExceededError(
                    this.props[MAX_FILE_SIZE_PROP_NAME]
                )
            );
            return;
        }

        this.setState(
            {
                file: this.mostRecentUploadedFile,
                error: null,
                status: STATUS.DONE,
            },
            this.triggerChange
        );
    };

    onUploadFailure = () => {
        this.updateStateOnFailure(this.fileReader.error);
    };

    updateStateOnFailure = (error) => {
        this.setState(
            {
                file: null,
                error,
                status: STATUS.ERROR,
            },
            this.triggerChange
        );
    };

    onUploadProgress = () => {
        this.setState(
            {
                file: null,
                error: null,
                status: STATUS.LOADING,
            },
            this.triggerChange
        );
    };

    abortIfUploadInProgress = () => {
        // Check if upload is in progress
        if (this.fileReader.readyState === 1) {
            this.fileReader.abort();
        }
    };

    handleAddFile = (files) => {
        if (!files || !files[0]) {
            return;
        }
        [this.mostRecentUploadedFile] = files;
        this.abortIfUploadInProgress();
        this.fileReader.readAsDataURL(this.mostRecentUploadedFile);
    };

    handleRemoveFile = () => {
        this.abortIfUploadInProgress();
        this.mostRecentUploadedFile = null;

        this.setState(
            {
                file: null,
                error: null,
                status: STATUS.EMPTY,
            },
            this.triggerChange
        );
    };

    render() {
        const { file, error } = this.state;
        const {
            onRequestAdd: skipOnRequestAdd,
            onRequestRemove: skipOnRequestRemove,
            onChange: skipOnChange,
            ...rest
        } = this.props;

        return (
            <>
                <File
                    onRequestAdd={this.handleAddFile}
                    onRequestRemove={this.handleRemoveFile}
                    data-test-name={TEST_IDS.FILE_UPLOAD}
                    {...rest}
                >
                    {/* {file && file.name && <File.Item name={file.name} />} */}
                    {file && file.name && (
                        <div
                            style={{
                                background: "rgb(225, 230, 235)",
                                paddingLeft: 10,
                                position: "relative",
                                textAlign: "left",
                            }}
                        >
                            {file.name}
                            <Remove
                                data-test-name={TEST_IDS.REMOVE_BTN}
                                onClick={this.handleRemoveFile}
                                style={{
                                    position: "absolute",
                                    cursor: "pointer",
                                    right: 10,
                                    top: 10,
                                }}
                            />
                        </div>
                    )}
                </File>
                {error && (
                    <Message type="error">
                        {error.message || _(GENERIC_ERROR_MESSAGE)}
                    </Message>
                )}
            </>
        );
    }
}

SingleFileUpload.propTypes = {
    onChange: PropTypes.func.isRequired,
    [MAX_FILE_SIZE_PROP_NAME]: PropTypes.number,
    onRequestAdd: PropTypes.func,
    onRequestRemove: PropTypes.func,
};
