import PropTypes from "prop-types";
import React, { Component } from "react";
import ToastMessages from "@splunk/react-toast-notifications/ToastMessages";
import { MessageBar } from "@shared/components/Message";

import {
    getPackage,
    installPackage,
    getPackages,
} from "@uploadedApps/services/APIService";

import {
    getTargetedAppInstallationStatus,
    getServerInfo,
} from "@shared/services/APIService";
import withPackageService from "@uploadedApps/hoc/PackageServiceHOC";
import AppModel from "@uploadedApps/hoc/PackageServiceHOC/AppModel";
import PollTask from "@shared/services/PollTaskService";
import PackageCredentialsStore from "@shared/stores/PackageCredentialsStore";
import { get } from "lodash";
import PollAppVettingStatus from "@uploadedApps/services/PollAppVettingStatus";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";
import { getInstanceType } from "@uploadedApps/utils";
import { INSTANCE_TYPES, TOKEN_EXPIRATION_TIME } from "@shared/constants";
import {
    APP_ACTION_MODAL_ACTIONS,
    APP_ACTION_MODAL_STATUSES,
} from "@shared/components/AppActionModal";
import {
    getTargetedAppInstallMessage,
    isAuthenticated,
} from "@shared/lib/utils";
import UploadedAppsPage from "./UploadedAppsPage.component";

class UploadedAppsPageContainer extends Component {
    constructor(props) {
        super(props);
        this.state = {
            /** Token used to upload packages */
            authToken: null,
            /** REST package object used to perform various actions: install, update, delete */
            currentPackage: null,
            /** Name of current file being uploaded */
            filename: "",
            /** All state var w/ open* map to the open/close of modals */
            openAcknowledgementModal: false,
            openDeleteModal: false,
            openInstallUpdateModal: false,
            openLoginModal: false,
            openMoreInfoModal: false,
            openUpdateModal: false,
            openUploadModal: false,
            openVettingProgressModal: false,
            openVettingErrorModal: false,
            installUpdateModalConfig: null,
            checkInstallationStatusModalConfig: null,
            /** Tracks num of vetting errors in vetting error modal */
            vettingErrorCount: 0,
            showTargetedAppInstallMessage: false,
            targetedAppInstallMessage: "",
        };
    }

    async componentDidMount() {
        if (
            !GlobalContextStore.get(KEYS.isDMC) &&
            (await getTargetedAppInstallationStatus())
        ) {
            const serverInfo = await getServerInfo();
            this.setState({
                showTargetedAppInstallMessage: true,
                targetedAppInstallMessage: getTargetedAppInstallMessage(
                    serverInfo,
                    true
                ),
            });
        }
    }

    getPrivateAppGlobal = () => GlobalContextStore.get(KEYS.privateAppGlobal);

    handleUploadSuccess = async ({ appUniqueId, authToken, fileName }) => {
        // For Noah privateAppGlobal is enabled by default.
        // For DMC, there still could be use cases when privateAppGlobal is disabled.
        if (this.getPrivateAppGlobal()) {
            // Private app global workflow
            this.setState({
                openVettingProgressModal: true,
                openUploadModal: false,
                filename: fileName,
            });
        }
        await this.props.packageService.refreshPackageListing();

        if (getInstanceType() === INSTANCE_TYPES.NOAH) {
            this.pollForVictoriaVettingStatus({
                appSHA: appUniqueId,
                authToken,
            });
        } else if (getInstanceType() === INSTANCE_TYPES.DMC) {
            if (this.getPrivateAppGlobal()) {
                this.pollForClassicVettingStatus(appUniqueId);
            } else {
                this.props.packageService.startPolling();
            }
        }
    };

    pollForVictoriaVettingStatus = async ({ appSHA, authToken }) => {
        if (!appSHA || !authToken) {
            return;
        }
        PackageCredentialsStore.set(appSHA, { authToken: authToken.value });
        try {
            const app = await PollAppVettingStatus.start({
                appSHA,
                authToken: authToken.value,
            });

            this.props.packageService.updatePackage(appSHA, {
                ...app,
                isFetchingStatus: false,
            });

            if (app.hasFailedAppVetting) {
                this.setState({
                    currentPackage: app,
                    openVettingErrorModal: true,
                    openVettingProgressModal: false,
                });
            } else {
                this.setState({
                    openVettingProgressModal: false,
                });
            }
        } catch (e) {
            this.props.packageService.updatePackage(appSHA, {
                isFetchingStatus: false,
            });
            this.setState({
                openVettingProgressModal: false,
            });
        }
    };

    pollForClassicVettingStatus = async (appUniqueId) => {
        try {
            const pollResp = await PollTask.start(appUniqueId);
            const packageId = get(pollResp, "entry[0].name");

            let currentPackage;
            if (!GlobalContextStore.get(KEYS.isDMCGetPackageAPIAvailable)) {
                const pkgResp = await getPackages();
                const pkgList = pkgResp.entry.map((pkg) => new AppModel(pkg));

                currentPackage = pkgList.find((pkg) => pkg.id === packageId);
            } else {
                currentPackage = new AppModel(await getPackage(packageId));
            }
            const vettingStatus = get(
                pollResp,
                "entry[0].content.payload.packageStatus"
            );
            if (vettingStatus === "approved") {
                this.setState({
                    currentPackage,
                    openVettingProgressModal: false,
                });
            } else {
                const failures = get(
                    pollResp,
                    "entry[0].content.stages[0].payload.statusData.info.failure"
                );

                // if we lack report link, it means there is something wrong with package upload.
                // we should open moreInfoModal instead of appVettingErrorModal
                const hasReport = !!get(currentPackage, "raw.links.report");

                this.setState({
                    currentPackage,
                    openVettingProgressModal: false,
                    openVettingErrorModal: hasReport,
                    openMoreInfoModal: !hasReport,
                    vettingErrorCount: failures,
                });
            }
            this.props.packageService.updatePackage(appUniqueId, {
                ...currentPackage,
                isFetchingStatus: false,
            });
        } catch (error) {
            this.props.packageService.updatePackage(appUniqueId, {
                isFetchingStatus: false,
            });
        }
    };

    handleUploadBtnClick = () => {
        let openLoginModal = true;
        let openUploadModal = false;

        if (isAuthenticated(this.state.authToken)) {
            openLoginModal = false;
            openUploadModal = true;
        }

        this.setState({ openLoginModal, openUploadModal });
    };

    // Handler function that closes all modals and clears shared state vars
    handleModalClose = () => {
        this.setState({
            currentPackage: null,
            filename: "",
            openAcknowledgementModal: false,
            openDeleteModal: false,
            openInstallUpdateModal: false,
            openVettingProgressModal: false,
            openLoginModal: false,
            openMoreInfoModal: false,
            openUpdateModal: false,
            openUploadModal: false,
            openVettingErrorModal: false,
            checkInstallationStatusModalConfig: null,
            installUpdateModalConfig: null,
        });
    };

    // Handler function to open the DeleteModal
    handleDeleteModalOpen = (currentPackage) => {
        this.setState({
            currentPackage,
            openDeleteModal: true,
        });
    };

    handleDeleteSuccess = (id) => {
        this.props.packageService.removePackage(id);
        this.props.packageService.refreshPackageListing();
    };

    handleLoginModalSuccess = ({ authToken }) => {
        if (!authToken) {
            return;
        }

        this.setState({
            authToken: {
                value: authToken,
                expiry: Date.now() + TOKEN_EXPIRATION_TIME,
            },
            openLoginModal: false,
            openUploadModal: true,
        });
    };

    handleMoreInfoModalOpen = (currentPackage) => {
        this.setState({
            currentPackage,
            openMoreInfoModal: true,
        });
    };

    usesAckModal = () =>
        getInstanceType() === INSTANCE_TYPES.NOAH || this.getPrivateAppGlobal();

    // Handler function to open InstallModal
    handleInstallModalOpen = (currentPackage) => {
        if (this.usesAckModal()) {
            //  Open ack modal, then install for private app global workflow
            this.setState({
                currentPackage,
                openAcknowledgementModal: true,
            });
        } else {
            this.setState({
                currentPackage,
                installUpdateModalConfig: {
                    action: APP_ACTION_MODAL_ACTIONS.install,
                    status: APP_ACTION_MODAL_STATUSES.info,
                    appName: currentPackage.name,
                    handleConfirm: () => this.handleInstallPackage(),
                    isOpen: true,
                    isWorking: false,
                },
                openInstallUpdateModal: false,
            });
        }
    };

    handleAppInstallationFinish = (appId) => {
        this.setState((prev) => ({
            ...prev,
            installUpdateModalConfig: null,
            checkInstallationStatusModalConfig: {
                isOpen: true,
                appId,
            },
        }));
    };

    // Install the package.
    handleInstallPackage = async () => {
        const { currentPackage } = this.state;
        this.setState({
            installUpdateModalConfig: {
                action: APP_ACTION_MODAL_ACTIONS.install,
                status: APP_ACTION_MODAL_STATUSES.info,
                appName: currentPackage.name,
                isOpen: true,
                isWorking: true,
            },
            openAcknowledgementModal: false,
        });

        try {
            const isDMC = GlobalContextStore.get(KEYS.isDMC);
            const targetedAppInstall = isDMC
                ? false
                : await getTargetedAppInstallationStatus();
            const installResp = await installPackage({
                appId: currentPackage.id,
                targetedAppInstall,
            });
            if (isDMC) {
                await PollTask.start(installResp.entry[0].name);
            }

            let appId;
            if (isDMC) {
                appId = get(currentPackage, "raw.content.@app.name");
            } else {
                appId = get(currentPackage, "raw.content.app_id");
            }

            this.setState((prev) => ({
                installUpdateModalConfig: {
                    ...prev.installUpdateModalConfig,
                    isWorking: false,
                    status: APP_ACTION_MODAL_STATUSES.success,
                    handleFinish: () => this.handleAppInstallationFinish(appId),
                },
            }));

            this.props.packageService.refreshPackageListing();
        } catch (error) {
            this.setState((prev) => ({
                installUpdateModalConfig: {
                    ...prev.installUpdateModalConfig,
                    errorMessage: error.message,
                    isWorking: false,
                    status: APP_ACTION_MODAL_STATUSES.error,
                },
            }));
        }
    };

    // Handler function to open InstallModal
    handleUpdateModalOpen = (currentPackage) => {
        if (this.usesAckModal()) {
            //  Open ack modal, then install for private app global workflow
            this.setState({
                currentPackage,
                openAcknowledgementModal: true,
            });
        } else {
            this.setState({
                currentPackage,
                installUpdateModalConfig: {
                    action: APP_ACTION_MODAL_ACTIONS.update,
                    status: APP_ACTION_MODAL_STATUSES.info,
                    app: { name: currentPackage.name },
                    handleConfirm: () => this.handleInstallPackage(),
                    isOpen: true,
                    isWorking: false,
                },
                openInstallUpdateModal: false,
            });
        }
    };

    render() {
        return (
            <>
                <ToastMessages position="top-center" />
                {this.state.showTargetedAppInstallMessage && (
                    <MessageBar
                        type="info"
                        onRequestRemove={() => {
                            this.setState({
                                showTargetedAppInstallMessage: false,
                            });
                        }}
                    >
                        {this.state.targetedAppInstallMessage}
                    </MessageBar>
                )}
                <UploadedAppsPage
                    authToken={this.state.authToken}
                    currentPackage={this.state.currentPackage}
                    filename={this.state.filename}
                    openAcknowledgementModal={
                        this.state.openAcknowledgementModal
                    }
                    openDeleteModal={this.state.openDeleteModal}
                    openInstallUpdateModal={this.state.openInstallUpdateModal}
                    openLoginModal={this.state.openLoginModal}
                    openMoreInfoModal={this.state.openMoreInfoModal}
                    openUpdateModal={this.state.openUpdateModal}
                    openUploadModal={this.state.openUploadModal}
                    openVettingProgressModal={
                        this.state.openVettingProgressModal
                    }
                    openVettingErrorModal={this.state.openVettingErrorModal}
                    installUpdateModalConfig={
                        this.state.installUpdateModalConfig
                    }
                    checkInstallationStatusModalConfig={
                        this.state.checkInstallationStatusModalConfig
                    }
                    vettingErrorCount={this.state.vettingErrorCount}
                    handleUploadSuccess={this.handleUploadSuccess}
                    handleDeleteModalOpen={this.handleDeleteModalOpen}
                    handleInstallModalOpen={this.handleInstallModalOpen}
                    handleModalClose={this.handleModalClose}
                    handleLoginModalSuccess={this.handleLoginModalSuccess}
                    handleMoreInfoModalOpen={this.handleMoreInfoModalOpen}
                    handleUpdateModalOpen={this.handleUpdateModalOpen}
                    handleUploadBtnClick={this.handleUploadBtnClick}
                    handleAckSuccess={this.handleInstallPackage}
                    handleDeleteSuccess={this.handleDeleteSuccess}
                />
            </>
        );
    }
}

UploadedAppsPageContainer.propTypes = {
    packageService: PropTypes.any,
};

export default withPackageService(UploadedAppsPageContainer);
