import PollSplunkEndpoint from "@shared/services/Polling";
import { getTaskEndpoint } from "@shared/services/APIService";
import { get } from "lodash";

const taskPollRegistry = new Map();

export const defaultValidationFn = (resp) => {
    const currTaskState = get(resp, "entry[0].content.state");
    const taskComplete =
        currTaskState && currTaskState !== "running" && currTaskState !== "new";
    if (taskComplete) {
        return true;
    }
    return false;
};

const setupTaskPoll = (taskId, pollingOptions) => {
    const { authToken, ...restPollingOptions } = pollingOptions;
    const taskPollingOpt = {
        timeout: 60 * 60 * 1000, // 60 min
        url: getTaskEndpoint(taskId, authToken),
        validationFn: defaultValidationFn,
        ...restPollingOptions,
    };
    return new PollSplunkEndpoint(taskPollingOpt);
};

const generateTaskMetadata = () => ({
    service: null,
    promise: null,
});

class PollTaskService {
    start = async (taskId, pollingOptions = {}) => {
        if (!taskPollRegistry.has(taskId)) {
            taskPollRegistry.set(taskId, generateTaskMetadata());
        }
        const pollMetadata = taskPollRegistry.get(taskId);
        if (!pollMetadata.service) {
            pollMetadata.service = setupTaskPoll(taskId, pollingOptions);
        }
        if (pollMetadata.service.isPolling) {
            return pollMetadata.promise;
        }
        pollMetadata.promise = pollMetadata.service.startPolling();
        return pollMetadata.promise;
    };

    stop = (taskId) => {
        const entry = taskPollRegistry.get(taskId);
        if (!entry || !entry.service || !entry.service.isPolling) {
            return;
        }
        entry.service.stopPolling();
    };
}

const PollTask = new PollTaskService();
export default PollTask;
