const subscribers = new Map();

const unsubscribe = (eventName, cb) => {
    const currSubscribers = subscribers.get(eventName) || [];
    const index = currSubscribers.findIndex((item) => item === cb);
    if (index === -1) {
        return;
    }
    currSubscribers.splice(index, 1);
    subscribers.set(eventName, currSubscribers);
};

class PubSub {
    subscribe = (eventName, cb) => {
        if (!subscribers.has(eventName)) {
            subscribers.set(eventName, []);
        }
        subscribers.get(eventName).push(cb);
        return unsubscribe.bind(this, eventName, cb);
    };

    publish = (eventName, payload) => {
        if (!subscribers.has(eventName)) {
            return;
        }
        for (const cb of subscribers.get(eventName)) {
            cb(payload);
        }
    };
}

// Singleton
export default new PubSub();
