import React, { Component } from "react";

import Button from "@splunk/react-ui/Button";
import Link from "@splunk/react-ui/Link";
import Message from "@shared/components/Message";
import Modal from "@splunk/react-ui/Modal";
import P from "@splunk/react-ui/Paragraph";
import PropTypes from "prop-types";
import Text from "@splunk/react-ui/Text";
import { get } from "lodash";
import {
    loginToDMC,
    loginToNoah,
    loginToSplunkbase,
} from "@shared/components/LoginModal/LoginModal.helper";
import TEST_IDS from "./LoginModal.testids";
import { MESSAGES } from "./LoginModal.messages";
import { INSTANCE_TYPES } from "./constants";

const loginAPI = {
    DMC: loginToDMC,
    NOAH: loginToNoah,
    SPLUNKBASE: loginToSplunkbase,
};

class LoginModal extends Component {
    constructor(props) {
        super(props);
        this.state = this.getInitialState();
    }

    getInitialState = () => ({
        password: "",
        username: "",
        isLoading: false,
        error: null,
    });

    extractErrorMessage = () => {
        const { error } = this.state;
        if (!error) {
            return "";
        }
        if (typeof error === "string") {
            return error in MESSAGES.ERROR
                ? MESSAGES.ERROR[error]
                : MESSAGES.ERROR.GENERIC_ERROR_MESSAGE;
        }
        return error.message || MESSAGES.ERROR.GENERIC_ERROR_MESSAGE;
    };

    handleFormSubmit = (event) => {
        if (event.key === "Enter") {
            event.preventDefault();
            this.handleLoginBtnClick();
        }
    };

    handleCancelBtnClick = () => {
        this.setState(
            {
                ...this.getInitialState(),
            },
            this.props.handleClose
        );
    };

    isLoginBtnDisabled = () => {
        return (
            this.state.isLoading ||
            !(this.state.username.length > 0 && this.state.password.length > 0)
        );
    };

    handleLoginBtnClick = async () => {
        this.setState({
            isLoading: true,
            error: null,
        });

        const { username, password } = this.state;

        try {
            const resp = await loginAPI[this.props.instanceType]({
                username,
                password,
            });
            let authToken;
            if (this.props.instanceType === INSTANCE_TYPES.SPLUNKBASE) {
                const parser = new DOMParser();
                const xmlDoc = parser.parseFromString(resp, "text/xml");
                authToken = get(
                    xmlDoc.getElementsByTagName("id"),
                    "[0].textContent"
                );
            } else {
                authToken = resp;
            }

            // In Splunkbase login case, the credential failure case
            // does not end up in the catch block, instead it ends up
            // here. If authToken is present it's a successful login
            let isSuccessful = true;
            if (this.props.instanceType === INSTANCE_TYPES.SPLUNKBASE) {
                isSuccessful = authToken;
            }
            if (isSuccessful) {
                // Reset username and password when login is successful
                this.setState(
                    {
                        ...this.getInitialState(),
                    },
                    () => {
                        this.props.onSuccess({
                            authToken,
                            error: null,
                        });
                    }
                );
            } else {
                // If authToken is undefined, it means the splunkbase login
                // failed. We handle the login failure here.
                this.setState({
                    error: resp,
                    isLoading: false,
                });
            }
        } catch (error) {
            this.setState({
                error,
                isLoading: false,
            });
        }
    };

    handleUsernameText = (e, { value }) => {
        this.setState({ username: value });
    };

    handlePasswordText = (e, { value }) => {
        this.setState({ password: value });
    };

    render() {
        return (
            <Modal
                open={this.props.open}
                style={{ width: "690px" }}
                onKeyDown={this.handleFormSubmit}
                data-test-name={TEST_IDS.MODAL}
                className="shared-appsremote-dialog shared-appsremote-dialog-login"
            >
                <Modal.Header
                    onRequestClose={this.handleCancelBtnClick}
                    title={MESSAGES.LOGIN[this.props.action]}
                />
                <Modal.Body>
                    {this.state.error && (
                        <Message type="error">
                            {this.extractErrorMessage()}
                        </Message>
                    )}
                    <P>{MESSAGES.LOGIN_MESSAGE[this.props.action]}</P>
                    <br />
                    <Text
                        autoFocus
                        data-test-name={TEST_IDS.USERNAME_INPUT}
                        onChange={this.handleUsernameText}
                        name="username"
                        placeholder="Username"
                        style={{ width: "300px", marginBottom: "10px" }}
                        value={this.state.username}
                    />
                    <Text
                        data-test-name={TEST_IDS.PASSWORD_INPUT}
                        onChange={this.handlePasswordText}
                        name="password"
                        placeholder="Password"
                        style={{ width: "300px" }}
                        type="password"
                        value={this.state.password}
                    />
                    <Link
                        to="http://www.splunk.com/page/lost_password"
                        openInNewContext
                    >
                        {MESSAGES.FORGOT_PASSWORD}
                    </Link>
                    <br />
                    <br />
                </Modal.Body>
                <Modal.Footer>
                    <Button
                        data-test-name={TEST_IDS.CANCEL_BTN}
                        label={MESSAGES.CANCEL}
                        onClick={this.handleCancelBtnClick}
                    />
                    <Button
                        appearance="primary"
                        data-test-name={TEST_IDS.SUBMIT_BTN}
                        disabled={this.isLoginBtnDisabled()}
                        label={MESSAGES.LOGIN_TITLE}
                        onClick={this.handleLoginBtnClick}
                        value={{
                            username: this.state.username,
                            password: this.state.password,
                        }}
                    />
                </Modal.Footer>
            </Modal>
        );
    }
}

LoginModal.propTypes = {
    handleClose: PropTypes.func.isRequired,
    open: PropTypes.bool.isRequired,
    onSuccess: PropTypes.func,
    instanceType: PropTypes.oneOf(["NOAH", "DMC", "SPLUNKBASE"]).isRequired,
    action: PropTypes.oneOf(["INSTALL", "UPLOAD", "UPDATE"]).isRequired,
    app: PropTypes.shape({}),
};

export default LoginModal;
