import React from "react";
import PropTypes from "prop-types";

import { getIconColor, getMessageIcon } from "./Message.helper";

const Message = ({ type, children, ...restProps }) => {
    return (
        <div
            data-test-type={type}
            data-test="message"
            style={{
                padding: "10px 0 10px 40px",
                marginBottom: "10px",
                position: "relative",
            }}
        >
            <span
                style={{
                    position: "absolute",
                    top: "7px",
                    left: 0,
                    width: "25px",
                    height: "calc(100% - 8px)",
                    textAlign: "center",
                    color: getIconColor(type),
                }}
            >
                {getMessageIcon(type)}
            </span>
            <span {...restProps}>{children}</span>
        </div>
    );
};

Message.propTypes = {
    type: PropTypes.oneOf(["error", "warning", "info", "success"]),
    children: PropTypes.node.isRequired,
};

export default Message;
