import PollSplunkEndpoint from "@shared/services/Polling";
import { fetchAppVettingStatusRaw } from "@uploadedApps/services/APIService";
import { get } from "lodash";
import { FINAL_STATUSES } from "@uploadedApps/UploadedAppsPage/PackagesTable/PackagesTable.constants";
import AppModel from "@uploadedApps/hoc/PackageServiceHOC/AppModel";

const appPollRegistry = new Map();

export const defaultValidationFn = (resp) => {
    const { appinspect_status: appVettingStatus } = get(
        resp,
        "entry[0].content"
    );
    return appVettingStatus && FINAL_STATUSES.has(appVettingStatus);
};

const setupPoll = (pollingOptions) => {
    const { appSHA, authToken, ...restPollingOptions } = pollingOptions;
    const pollingOpt = {
        timeout: 15 * 60 * 1000, // 15 min
        makeRequestFn: fetchAppVettingStatusRaw.bind(null, {
            appSHA,
            authToken,
        }),
        validationFn: defaultValidationFn,
        ...restPollingOptions,
    };
    return new PollSplunkEndpoint(pollingOpt);
};

const generateMetadata = () => ({
    service: null,
    promise: null,
});

class PollAppVettingStatusService {
    start = async (pollingOptions = {}) => {
        const { appSHA } = pollingOptions;
        if (!appPollRegistry.has(appSHA)) {
            appPollRegistry.set(appSHA, generateMetadata());
        }
        const pollMetadata = appPollRegistry.get(appSHA);
        if (!pollMetadata.service) {
            pollMetadata.service = setupPoll(pollingOptions);
        }
        if (pollMetadata.service.isPolling) {
            return pollMetadata.promise;
        }
        pollMetadata.promise = pollMetadata.service
            .startPolling()
            .then((resp) => new AppModel(get(resp, "entry[0]")));
        return pollMetadata.promise;
    };

    stop = (appSHA) => {
        const entry = appPollRegistry.get(appSHA);
        const isPolling = get(entry, "service.isPolling", false);
        if (!isPolling) {
            return;
        }
        entry.service.stopPolling();
    };
}

const PollAppVettingStatus = new PollAppVettingStatusService();
export default PollAppVettingStatus;
