import { convertJSONToFormEncodedData, parseError } from "@shared/lib/utils";
import {
    defaultFetchInit,
    handleResponse,
    handleError,
} from "@splunk/splunk-utils/fetch";
import querystring from "querystring";
import { createRESTURL } from "@splunk/splunk-utils/url";
import { get } from "lodash";

import { MESSAGES } from "./LoginModal.messages";

export const loginToDMC = (credentials) => {
    const { headers } = defaultFetchInit;

    return fetch(createRESTURL("dmc/packages-upload:login"), {
        method: "POST",
        body: JSON.stringify(credentials),
        headers: {
            ...headers,
            "Content-Type": "application/json",
        },
    })
        .then(handleResponse(200))
        .then((resp) => get(resp, "entry[0].content"))
        .catch(handleError(MESSAGES.ERROR.UNABLE_TO_LOGIN));
};

export const loginToNoah = ({ username, password }) => {
    const { headers } = defaultFetchInit;

    return fetch(createRESTURL("uploaded-apps/package?output_mode=json"), {
        method: "POST",
        body: convertJSONToFormEncodedData({
            _action: "login",
            username,
            password,
        }),
        headers,
    })
        .then(handleResponse(200))
        .then((resp) => get(resp, "entry[0].content.auth_token"))
        .catch(parseError);
};

export const loginToSplunkbase = (credentials) => {
    const { headers } = defaultFetchInit;
    return fetch(createRESTURL("appsbrowser/account:login"), {
        method: "POST",
        body: querystring.encode(credentials),
        headers: {
            ...headers,
            "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
        },
    })
        .then((res) => {
            return res.text();
        })
        .catch(handleError(MESSAGES.ERROR.UNABLE_TO_LOGIN));
};
