import MESSAGES from "@uploadedApps/messages";
import {
    FINAL_STATUSES,
    APP_INSPECT_STATUSES,
    FAILED_APP_VETTING_STATUSES,
} from "@uploadedApps/UploadedAppsPage/PackagesTable/PackagesTable.constants";
import { getAppName, getInstanceType } from "@uploadedApps/utils";
import { get } from "lodash";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";
import { INSTANCE_TYPES } from "@shared/constants";

export default class AppModel {
    id;

    name;

    status;

    submittedDate;

    version;

    canUpdate;

    raw;

    isFetchingStatus = false;

    isFetchingReport = false;

    constructor(app) {
        const instanceType = getInstanceType();
        if (instanceType === INSTANCE_TYPES.DMC) {
            this.id = app.name;
            this.name = getAppName(app);
            this.status = get(app, "content.status", "");
            this.submittedDate = get(app, "content.submittedAt");
            this.version = get(app, "content.@app.version", MESSAGES.COMMON.NA);
            this.canUpdate = !!get(app, "links.update");
            this.errors = get(app, "content.@errors");
        } else if (instanceType === INSTANCE_TYPES.NOAH) {
            const appData = app.content || {};
            this.id = appData.app_sha;
            this.name = appData.app_name || appData.app_id;
            this.status = appData.appinspect_status;
            this.submittedDate = appData.upload_time;
            this.version = appData.app_version || MESSAGES.COMMON.NA;
            this.canUpdate = false;
            this.errors = null;
        }
        this.raw = app;
        this.raw.appModel = this;
    }

    get canInstall() {
        const app = this.raw || {};
        if (getInstanceType() === INSTANCE_TYPES.DMC) {
            return !!get(app, "links.install");
        }
        const isAlreadyInstalled = get(app, "content.app_installed");
        if (isAlreadyInstalled) {
            return false;
        }
        if (!GlobalContextStore.get(KEYS.requireAppInspect)) {
            return true;
        }
        return this.status === APP_INSPECT_STATUSES.SUCCESS;
    }

    get hasReport() {
        const app = this.raw;
        if (getInstanceType() === INSTANCE_TYPES.DMC) {
            return !!get(app, "links.report");
        }
        return FINAL_STATUSES.has(get(app, "content.appinspect_status"));
    }

    get hasFailedAppVetting() {
        return FAILED_APP_VETTING_STATUSES.has(this.status);
    }

    get canDelete() {
        const app = this.raw || {};
        if (getInstanceType() === INSTANCE_TYPES.DMC) {
            return !!get(app, "links.delete");
        }

        return (
            FINAL_STATUSES.has(get(app, "content.appinspect_status")) &&
            !get(app, "content.app_installed")
        );
    }
}
