import React from "react";

export function boldText(str, subStr) {
    const strArr = str.split(subStr);

    if (str.length === 0) {
        return <b>{subStr}</b>;
    }
    if (subStr.length === 0) {
        return <span>{str}</span>;
    }

    return (
        <span>
            {strArr.map((partStr, index) => (
                <React.Fragment key={`${partStr}-${index + 1}`}>
                    {partStr}
                    {index !== strArr.length - 1 && (
                        <b key={subStr}>{subStr}</b>
                    )}
                </React.Fragment>
            ))}
        </span>
    );
}
