export const APP_ACTION_MODAL_STATUSES = Object.freeze({
    info: "info",
    success: "success",
    error: "error",
});

export const APP_ACTION_MODAL_STATES = Object.freeze({
    confirm: "confirm",
    inProgress: "inProgress",
    success: "success",
    error: "error",
});

export const APP_ACTION_MODAL_ACTIONS = Object.freeze({
    install: "install",
    update: "update",
    setup: "setup",
    enable: "enable",
});

export const statusToStateMapper = (status, isWorking) => {
    if (status === APP_ACTION_MODAL_STATUSES.info) {
        return isWorking
            ? APP_ACTION_MODAL_STATES.inProgress
            : APP_ACTION_MODAL_STATES.confirm;
    }
    if (status === APP_ACTION_MODAL_STATUSES.success) {
        return APP_ACTION_MODAL_STATES.success;
    }
    return status === APP_ACTION_MODAL_STATUSES.error
        ? APP_ACTION_MODAL_STATES.error
        : "";
};

export const isFooterVisibleByState = (actionState) =>
    [
        APP_ACTION_MODAL_STATES.confirm,
        APP_ACTION_MODAL_STATES.error,
        APP_ACTION_MODAL_STATES.success,
    ].includes(actionState);
