import {
    HTTP_ERROR_CODE,
    SPLUNK_DOCS_PRIVATE_APPS_URL,
} from "@uploadedApps/constants";
import { isNil } from "lodash";

import Button from "@splunk/react-ui/Button";
import Link from "@splunk/react-ui/Link";
import MESSAGES from "@uploadedApps/messages";
import Message from "@shared/components/Message";
import Modal from "@splunk/react-ui/Modal";
import PropTypes from "prop-types";
import React from "react";
import { acknowledgeRisk } from "@uploadedApps/services/APIService";
import { getInstanceType } from "@uploadedApps/utils";
import { INSTANCE_TYPES } from "@shared/constants";
import TEST_IDS from "./AcknowledgementModal.testids";

export default class AcknowledgementModal extends React.Component {
    constructor(props) {
        super(props);
        this.state = this.getInitialStateConfig();
    }

    getInitialStateConfig = () => ({
        errorMessage: "",
        isLoading: false,
    });

    handleAckRequest = async () => {
        // For Noah, we don't need to make the API call in phase 1
        if (getInstanceType() === INSTANCE_TYPES.NOAH) {
            this.onSuccess();
            return;
        }
        if (isNil(this.props, "app.id")) {
            return;
        }
        this.setState({
            isLoading: true,
        });

        try {
            await acknowledgeRisk(this.props.app.id);
            this.onSuccess();
        } catch (error) {
            if (error.status === HTTP_ERROR_CODE.METHOD_NOT_ALLOWED) {
                // Due to feature flag, Ack request will fail with 405 status if
                // feature not enabled on both SH and CM. This if statement will
                // allow user to still install app.
                this.onSuccess();
            } else {
                this.setState({
                    errorMessage:
                        MESSAGES.ACKNOWLEDGEMENT_MODAL.ACKNOWLEDGEMENT_FAILED,
                    isLoading: false,
                });
            }
        }
    };

    onSuccess = () => {
        this.setState(
            {
                errorMessage: "",
                isLoading: false,
            },
            this.props.onSuccess
        );
    };

    handleClose = () => {
        this.setState(
            {
                ...this.getInitialStateConfig(),
            },
            this.props.handleClose
        );
    };

    render() {
        const { errorMessage, isLoading } = this.state;
        const { open } = this.props;

        return (
            <div>
                <Modal
                    data-test-name={TEST_IDS.MODAL}
                    onRequestClose={this.handleClose}
                    open={open}
                >
                    <Modal.Header
                        title={MESSAGES.ACKNOWLEDGEMENT_MODAL.MODAL_TITLE}
                        onRequestClose={this.handleClose}
                    />
                    <Modal.Body>
                        {errorMessage && (
                            <Message type="error">{errorMessage}</Message>
                        )}
                        <Message type="success">
                            <p>
                                {
                                    MESSAGES.ACKNOWLEDGEMENT_MODAL
                                        .ACKNOWLEDGE_DESCRIPTION
                                }
                                <Link
                                    to={SPLUNK_DOCS_PRIVATE_APPS_URL}
                                    openInNewContext
                                >
                                    {MESSAGES.ACKNOWLEDGEMENT_MODAL.LEARN_MORE}
                                </Link>
                            </p>
                        </Message>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button
                            data-test-name={TEST_IDS.CLOSE_BTN}
                            onClick={this.handleClose}
                            label={MESSAGES.COMMON.CANCEL}
                        />
                        <Button
                            appearance="primary"
                            data-test-name={TEST_IDS.INSTALL_BTN}
                            disabled={isLoading}
                            onClick={this.handleAckRequest}
                            label={
                                isLoading
                                    ? MESSAGES.COMMON.WORKING
                                    : MESSAGES.ACKNOWLEDGEMENT_MODAL
                                          .ACK_AND_INSTALL
                            }
                        />
                    </Modal.Footer>
                </Modal>
            </div>
        );
    }
}

AcknowledgementModal.propTypes = {
    handleClose: PropTypes.func.isRequired,
    open: PropTypes.bool.isRequired,
    app: PropTypes.any,
    onSuccess: PropTypes.func,
};
