import PropTypes from "prop-types";
import React from "react";
import Button from "@splunk/react-ui/Button";
// import Message from "@splunk/react-ui/Message";
import Message from "@shared/components/Message";
import Modal from "@splunk/react-ui/Modal";

import MESSAGES from "@uploadedApps/messages";
import { getTitle, getMessages } from "./MoreInfoModal.utils";
import TEST_IDS from "./MoreInfoModal.testids";

const MoreInfoModal = (props) => {
    const { app } = props;
    return (
        <Modal data-test-name={TEST_IDS.MODAL} open={props.open}>
            <Modal.Header
                onRequestClose={props.handleClose}
                title={app && getTitle(app)}
            />
            <Modal.Body>
                {app && <Message type="error">{getMessages(app)}</Message>}
            </Modal.Body>
            <Modal.Footer>
                <Button
                    data-test-name={TEST_IDS.CLOSE_BTN}
                    label={MESSAGES.COMMON.CLOSE}
                    onClick={props.handleClose}
                />
            </Modal.Footer>
        </Modal>
    );
};

MoreInfoModal.propTypes = {
    app: PropTypes.any,
    handleClose: PropTypes.func.isRequired,
    open: PropTypes.bool.isRequired,
};

export default MoreInfoModal;
