import * as React from "react";
import PollPackagesCollection from "@uploadedApps/services/PollPackagesCollectionService";
import { getPackages } from "@uploadedApps/services/APIService";
import PubSub from "@shared/lib/PubSub";
import { noop, getComponentDisplayName } from "@shared/lib/utils";
import { cloneDeep } from "lodash";
import { parsePackages, getTotalCount } from "./PackageServiceHOC.helper";

const EVENT_UPDATE_PACKAGES = "EVENT_UPDATE_PACKAGES";

const withPackageService = (WrappedComponent) => {
    class WithPackageService extends React.Component {
        state = {
            packages: [],
            totalCount: 0,
            error: null,
        };

        unsubscribe = noop;

        componentDidMount() {
            this.unsubscribe = PubSub.subscribe(
                EVENT_UPDATE_PACKAGES,
                this.updateState
            );
        }

        componentWillUnmount() {
            this.unsubscribe();
        }

        startPolling = () => {
            PollPackagesCollection.start().then((resp) => {
                const packages = parsePackages(resp);
                // Publish the latest data
                PubSub.publish(EVENT_UPDATE_PACKAGES, {
                    packages,
                    totalCount: getTotalCount(resp),
                });
            });
        };

        updateState = ({
            packages,
            totalCount = this.state.totalCount,
            /* isLoading, */ error,
        }) => {
            this.setState({
                packages: Array.isArray(packages) ? packages : [],
                totalCount,
                // isLoading: !!isLoading,
                error,
            });
        };

        updatePackage = (id, fieldValues) => {
            const packages = [...this.state.packages];
            const targetPackageIndex = packages.findIndex(
                (app) => app.id === id
            );
            if (targetPackageIndex === -1) {
                return;
            }
            const newPackageData = cloneDeep(packages[targetPackageIndex]);
            for (const key of Object.keys(fieldValues)) {
                newPackageData[key] = fieldValues[key];
            }
            packages[targetPackageIndex] = newPackageData;
            PubSub.publish(EVENT_UPDATE_PACKAGES, {
                packages,
            });
        };

        removePackage = (id) => {
            const pkgs = this.state.packages.filter((pkg) => pkg.id !== id);
            PubSub.publish(EVENT_UPDATE_PACKAGES, {
                packages: pkgs,
                totalCount: this.state.totalCount - 1,
            });
        };

        addNewPackages = async () => {
            const prevPackages = this.state.packages;
            const prevPackagesIds = new Set();
            prevPackages.forEach((pkg) => {
                prevPackagesIds.add(pkg.id);
            });
            try {
                const resp = await getPackages();
                const newPackages = parsePackages(resp);

                const packagesCopy = [...this.state.packages];
                for (let i = 0; i < newPackages.length; i += 1) {
                    if (!prevPackagesIds.has(newPackages[i].id)) {
                        packagesCopy.push(newPackages[i]);
                    }
                }
                PubSub.publish(EVENT_UPDATE_PACKAGES, {
                    packages: packagesCopy,
                    totalCount: getTotalCount(resp),
                });
            } catch (error) {
                console.error("Error fetching packages", error);
            }
        };

        // Helper function to fetch packages and update the listing table
        refreshPackageListing = async (payload = {}) => {
            try {
                const resp = await getPackages(payload);
                const packages = parsePackages(resp);
                const totalCount = getTotalCount(resp);

                PubSub.publish(EVENT_UPDATE_PACKAGES, {
                    packages,
                    totalCount,
                });
                return {
                    packages,
                    error: null,
                };
            } catch (error) {
                PubSub.publish(EVENT_UPDATE_PACKAGES, {
                    packages: [],
                    totalCount: 0,
                    error,
                });
                return {
                    packages: [],
                    error,
                };
            }
        };

        prepareProps = () => {
            const { packages, totalCount, /* isLoading, */ error } = this.state;

            return {
                packageService: {
                    packages,
                    totalCount,
                    // isLoading,
                    error,
                    refreshPackageListing: this.refreshPackageListing,
                    startPolling: this.startPolling,
                    updatePackage: this.updatePackage,
                    removePackage: this.removePackage,
                    addNewPackages: this.addNewPackages,
                },
                ...this.props, // pass over the originally passed props
            };
        };

        render() {
            return <WrappedComponent {...this.prepareProps()} />;
        }
    }

    WithPackageService.displayName = `WithPackageService(${getComponentDisplayName(
        WrappedComponent
    )})`;

    return WithPackageService;
};

export default withPackageService;
