import PropTypes from "prop-types";
import React from "react";
import { createRESTURL } from "@splunk/splunk-utils/url";
import Link from "@splunk/react-ui/Link";
import Table from "@splunk/react-ui/Table";
import Tooltip from "@splunk/react-ui/Tooltip";
import WaitSpinner from "@splunk/react-ui/WaitSpinner";
import { get } from "lodash";
import ActionLink from "@shared/components/ActionLink";
import MESSAGES from "@uploadedApps/messages";
import withPackageService from "@uploadedApps/hoc/PackageServiceHOC";
import {
    fetchAppVettingStatus,
    fetchReportForNoah,
    getLastDeployTask,
} from "@uploadedApps/services/APIService";
import { getTaskStatus } from "@shared/services/APIService";
import PollTask from "@shared/services/PollTaskService";
import PollDeploy from "@shared/services/PollDeployService";
import { getInstanceType } from "@uploadedApps/utils";
import { INSTANCE_TYPES, SORT_DIR } from "@shared/constants";
import PackageCredentialsStore from "@shared/stores/PackageCredentialsStore";
import GlobalContextStore, { KEYS } from "@shared/stores/GlobalContextStore";
import { formatDateIfEpoch, renderContentInNewWindow } from "@shared/lib/utils";
import PollAppVettingStatus from "@uploadedApps/services/PollAppVettingStatus";
import { TOAST_TYPES } from "@splunk/react-toast-notifications/ToastConstants";
import createToast from "@uploadedApps/UploadedAppsPage/CreateToast";

import {
    ACTION_AFTER_AUTH,
    STATUSES as PACKAGE_STATUS,
    STATUSES,
    TABLE_HEADER,
} from "./PackagesTable.constants";
import TEST_IDS from "./PackagesTable.testids";
import {
    isStatusFailed,
    getStatus,
    isVetting,
    isStatusAvailable,
    getStatusMessageForNoah,
} from "./PackagesTable.helper";
import CheckAppStatus from "./CheckAppStatus";
import TableActions from "./TableActions";

class PackagesTable extends React.Component {
    state = {
        deploymentInProgress: false,
        openCheckAppStatusModal: false,
        packageFetchingDone: true,
        sorting: {
            sortKey: TABLE_HEADER[getInstanceType()].UPLOAD_TIME,
            sortDir: SORT_DIR.DESC,
        },
    };

    /** Package ID of the most recent deployTask */
    lastDeployTask;

    latestDeployPoll;

    checkStatusForPackage = null;

    performActionAfterAuth;

    componentDidMount = async () => {
        this.loadPackages();
        if (getInstanceType() === INSTANCE_TYPES.DMC) {
            this.pollLastDeployTaskForDMC();
        }
    };

    componentWillUnmount() {
        PollDeploy.stop();
        PollTask.stop(this.lastDeployTask);
    }

    canUserEdit = () => GlobalContextStore.get(KEYS.canEdit);

    loadPackages = async () => {
        this.setState({
            packageFetchingDone: false,
        });
        const {
            packages = [],
            error,
        } = await this.props.packageService.refreshPackageListing({
            sorting: this.state.sorting,
        });
        this.setState({
            packageFetchingDone: true,
        });

        if (getInstanceType() === INSTANCE_TYPES.NOAH || error) {
            return;
        }

        // Check if there's any app which is currently vetting
        const isAnyAppVetting = packages.some(
            (pkg) => pkg.status === STATUSES.vetting
        );
        if (isAnyAppVetting) {
            this.props.packageService.startPolling();
        }
    };

    pollLastDeployTaskForDMC = async () => {
        try {
            const resp = await getLastDeployTask();
            this.lastDeployTask = get(resp, "entry[0].content.taskId");
            // Check the latest task state to see if it is in progress
            this.checkLatestTaskForDMC();

            // poll deploy endpoint to check when a new task has started
            PollDeploy.start({
                onEachIteration: this.onEachIterationOfPollDeploy,
            });
        } catch (error) {
            console.error(`Error fetching last deploy task`, error);
        }
    };

    onEachIterationOfPollDeploy = (resp) => {
        const lastDeployTask = get(resp, "entry[0].content.taskId", "");
        if (lastDeployTask !== this.lastDeployTask) {
            // If latest deployTask doesn't match existing, store new deployTask
            this.lastDeployTask = lastDeployTask;
            this.checkLatestTaskForDMC();
        }
    };

    checkLatestTaskForDMC = () => {
        if (!this.lastDeployTask || getInstanceType() !== INSTANCE_TYPES.DMC) {
            return;
        }
        // Call tasks endpoint to get taskState
        getTaskStatus(this.lastDeployTask).then((taskResp) => {
            const taskState = get(taskResp, "entry[0].content.state");
            const taskInProgress =
                taskState && (taskState === "running" || taskState === "new");
            // If the last deployed task is inProgress, poll it until completion
            if (taskInProgress) {
                // Block other tasks from starting
                this.setState({ deploymentInProgress: true });
                PollTask.start(this.lastDeployTask).then(() => {
                    // Once latestTask is in complete state, set deploymentInProgress to false to
                    // unblock other tasks from starting and update packagesCollection
                    this.setState({ deploymentInProgress: false });
                    this.props.packageService.refreshPackageListing();
                });
            }
        });
    };

    /**
     * See if the package has its dedicated auth token, if there is one, then use that.
     * Otherwise check if there is a default auth token, if there is one, then use that.
     * If neither is present, then request user to authenticate
     * @param {Object} row App record
     */
    attemptToFetchAppStatus = async (app) => {
        const { id: appSHA } = app;
        const packageInfo = PackageCredentialsStore.get(appSHA);
        const packageAuthToken = packageInfo && packageInfo.authToken;
        const defaultAuthToken = PackageCredentialsStore.getDefaultAuthToken();
        let shouldUserAuthenticate = true;
        const isUsingDefaultAuthToken = Boolean(
            !packageAuthToken && defaultAuthToken
        );
        // If either of the tokens are present, we can attempt to fetch the app vetting status
        if (packageAuthToken || defaultAuthToken) {
            shouldUserAuthenticate = false;
            this.props.packageService.updatePackage(appSHA, {
                isFetchingStatus: true,
            });
            const {
                app: updatedApp,
                error,
            } = await this.retrieveAppVettingStatus({
                authToken: packageAuthToken || defaultAuthToken,
                appSHA,
            });
            this.props.packageService.updatePackage(appSHA, {
                ...updatedApp,
                isFetchingStatus: false,
            });
            if (error) {
                if (isUsingDefaultAuthToken) {
                    shouldUserAuthenticate = true;
                } else {
                    createToast({
                        type: TOAST_TYPES.ERROR,
                        message: MESSAGES.ERRORS.GENERIC_ERROR_MESSAGE,
                        autoDismiss: true,
                        dismissOnActionClick: true,
                        showAction: false,
                    });
                }
            } else {
                if (isUsingDefaultAuthToken) {
                    // Update PackageCredentialsStore since the authToken worked.
                    PackageCredentialsStore.set(appSHA, {
                        authToken: defaultAuthToken,
                    });
                }
                if (!isStatusAvailable(updatedApp.status)) {
                    this.pollToUpdatePackageStatus({
                        appSHA,
                        authToken: isUsingDefaultAuthToken
                            ? defaultAuthToken
                            : packageAuthToken,
                    });
                }
            }
        }
        if (shouldUserAuthenticate) {
            this.requestUserToAuthenticate({
                app,
                action: ACTION_AFTER_AUTH.CHECK_STATUS,
            });
        }
    };

    retrieveAppVettingStatus = async ({ authToken, appSHA }) => {
        try {
            const app = await fetchAppVettingStatus({
                authToken,
                appSHA,
            });
            return { app, error: null };
        } catch (error) {
            return { error };
        }
    };

    openAppReport = async (row) => {
        let authToken = PackageCredentialsStore.getDefaultAuthToken();
        if (PackageCredentialsStore.get(row.id)) {
            authToken = PackageCredentialsStore.get(row.id).authToken;
        }
        if (!authToken) {
            this.requestUserToAuthenticate({
                app: row,
                action: ACTION_AFTER_AUTH.FETCH_REPORT,
            });
            return;
        }
        this.fetchAppReport({ app: row, authToken });
    };

    requestUserToAuthenticate = ({ app, action }) => {
        // request user to authenticate
        this.checkStatusForPackage = app;
        this.performActionAfterAuth = action;
        this.setState({
            openCheckAppStatusModal: true,
        });
    };

    fetchAppReport = async ({ app, authToken }) => {
        const { id: appId } = app;
        try {
            this.props.packageService.updatePackage(appId, {
                isFetchingReport: true,
            });
            const response = await fetchReportForNoah({
                appSHA: appId,
                authToken,
            });
            if (response) {
                renderContentInNewWindow(response);
            }
        } catch (error) {
            this.requestUserToAuthenticate({
                app,
                action: ACTION_AFTER_AUTH.FETCH_REPORT,
            });
        } finally {
            this.props.packageService.updatePackage(appId, {
                isFetchingReport: false,
            });
        }
    };

    getPackageStatusComp = (row) => {
        const isPrivateAppGlobal = GlobalContextStore.get(
            KEYS.privateAppGlobal
        );
        const statusToolTip = (
            <Tooltip
                style={{ marginLeft: 4 }}
                content={MESSAGES.PACKAGES_TABLE.VALIDATING_TOOLTIP_CONTENT}
                defaultPlacement="above"
            />
        );
        const { status, isFetchingStatus } = row;
        const result = [];

        if (isFetchingStatus || isVetting(status)) {
            result.push(
                <WaitSpinner
                    key={`loading-${row.id}`}
                    style={{ marginRight: 10 }}
                    data-test-name={TEST_IDS.WAIT_SPINNER}
                />
            );
        }

        if (getInstanceType() === INSTANCE_TYPES.NOAH) {
            const showCheckStatusLink =
                !isStatusAvailable(status) && !row.isFetchingStatus;

            if (showCheckStatusLink) {
                result.push(
                    <ActionLink
                        key={`status-link-${row.id}`}
                        label={MESSAGES.PACKAGES_TABLE.CHECK_STATUS_LINK}
                        testHook={MESSAGES.PACKAGES_TABLE.CHECK_STATUS_LINK}
                        clickHandler={() => this.attemptToFetchAppStatus(row)}
                    />
                );
            } else {
                result.push(
                    <span
                        style={{ marginRight: 20 }}
                        key={`status-message-${row.id}`}
                    >
                        {getStatusMessageForNoah(row)}
                        {row.isFetchingStatus &&
                            isPrivateAppGlobal &&
                            statusToolTip}
                    </span>
                );
            }
            return result;
        }

        // is DMC
        result.push(
            <div
                key={`status-${row.id}`}
                style={{
                    display: "inline-block",
                    marginRight: "10px",
                }}
            >
                {isStatusFailed(status) ? (
                    MESSAGES.PACKAGES_TABLE.APP_VETTING_ERROR_MESSAGE
                ) : (
                    <>
                        {isPrivateAppGlobal &&
                        getStatus(status) ===
                            MESSAGES.PACKAGES_TABLE.STATUSES[
                                PACKAGE_STATUS.vetting
                            ]
                            ? MESSAGES.PACKAGES_TABLE.STATUSES[
                                  PACKAGE_STATUS.validating
                              ]
                            : getStatus(status)}
                        {isVetting(status) &&
                            isPrivateAppGlobal &&
                            statusToolTip}
                    </>
                )}
            </div>
        );
        if (
            this.canUserEdit() &&
            (row.raw.content["@errors"] || isStatusFailed(status))
        ) {
            result.push(
                <ActionLink
                    key={`more-info-${row.id}`}
                    label={MESSAGES.COMMON.MORE_INFO}
                    testHook={MESSAGES.COMMON.MORE_INFO}
                    clickHandler={() => this.props.handleMoreInfoModalOpen(row)}
                    disabled={false}
                />
            );
        }

        return result;
    };

    getActionsComp = (row) => {
        if (!this.canUserEdit()) {
            return null;
        }

        return [
            row.canInstall && (
                <ActionLink
                    key={`install-${row.id}`}
                    label={MESSAGES.COMMON.INSTALL}
                    testHook={MESSAGES.COMMON.INSTALL}
                    clickHandler={() => this.props.handleInstallModalOpen(row)}
                    disabled={this.state.deploymentInProgress}
                />
            ),
            row.canUpdate && (
                <ActionLink
                    key={`update-${row.id}`}
                    label={MESSAGES.COMMON.UPDATE}
                    testHook={MESSAGES.COMMON.UPDATE}
                    clickHandler={() => this.props.handleUpdateModalOpen(row)}
                    disabled={this.state.deploymentInProgress}
                />
            ),
            row.canDelete && (
                <ActionLink
                    key={`delete-${row.id}`}
                    label={MESSAGES.COMMON.DELETE}
                    testHook={MESSAGES.COMMON.DELETE}
                    clickHandler={() => this.props.handleDeleteModalOpen(row)}
                    disabled={this.state.deploymentInProgress}
                />
            ),
            row.hasReport &&
                (getInstanceType() === INSTANCE_TYPES.DMC ? (
                    <Link
                        key={`report-${row.id}`}
                        data-test-name={TEST_IDS.VIEW_REPORT}
                        openInNewContext
                        to={createRESTURL(get(row, "raw.links.report", ""))}
                    >
                        {MESSAGES.COMMON.VIEW_REPORT}
                    </Link>
                ) : (
                    <ActionLink
                        key={`report-${row.id}`}
                        label={
                            row.isFetchingReport
                                ? MESSAGES.PACKAGES_TABLE.FETCHING_REPORT
                                : MESSAGES.COMMON.VIEW_REPORT
                        }
                        testHook={MESSAGES.COMMON.VIEW_REPORT}
                        clickHandler={() => this.openAppReport(row)}
                        disabled={row.isFetchingReport}
                    />
                )),
        ];
    };

    handleCheckAppStatusSuccess = ({ authToken, updatedApp }) => {
        if (this.performActionAfterAuth === ACTION_AFTER_AUTH.FETCH_REPORT) {
            PackageCredentialsStore.set(this.checkStatusForPackage.id, {
                authToken,
            });
            return;
        }
        const { id: appSHA } = updatedApp;
        PackageCredentialsStore.set(appSHA, { authToken });
        this.props.packageService.updatePackage(appSHA, {
            ...updatedApp,
        });
        if (isStatusAvailable(updatedApp.status)) {
            return;
        }
        this.pollToUpdatePackageStatus({ appSHA, authToken });
    };

    pollToUpdatePackageStatus = async ({ appSHA, authToken }) => {
        if (!appSHA || !authToken) {
            return;
        }
        this.props.packageService.updatePackage(appSHA, {
            isFetchingStatus: true,
        });
        try {
            const app = await PollAppVettingStatus.start({
                appSHA,
                authToken,
            });
            this.props.packageService.updatePackage(appSHA, {
                ...app,
                isFetchingStatus: false,
            });
        } catch (e) {
            this.props.packageService.updatePackage(appSHA, {
                isFetchingStatus: false,
            });
        }
    };

    hideCheckAppStatusModal = () => {
        this.checkStatusForPackage = null;
        this.performActionAfterAuth = undefined;
        this.setState({
            openCheckAppStatusModal: false,
        });
    };

    handleSort = (e, { sortKey }) => {
        this.setState(
            (prevState) => {
                const prevSortKey = prevState.sorting.sortKey;
                const prevSortDir =
                    prevSortKey === sortKey
                        ? prevState.sorting.sortDir
                        : SORT_DIR.NONE;
                const nextSortDir =
                    prevSortDir === SORT_DIR.ASC ? SORT_DIR.DESC : SORT_DIR.ASC;
                return {
                    sorting: {
                        sortKey,
                        sortDir: nextSortDir,
                    },
                };
            },
            () => {
                this.props.packageService.refreshPackageListing({
                    sorting: this.state.sorting,
                });
            }
        );
    };

    generateHederCellProps = (colName) => {
        const colId = TABLE_HEADER[getInstanceType()][colName];

        return getInstanceType() === INSTANCE_TYPES.NOAH
            ? {
                  key: colId,
                  columnId: colId,
                  onSort: this.handleSort,
                  sortKey: colId,
                  sortDir:
                      colId === this.state.sorting.sortKey
                          ? this.state.sorting.sortDir
                          : SORT_DIR.NONE,
              }
            : {};
    };

    render() {
        const { packages } = this.props.packageService;

        return (
            <div
                data-test-name={TEST_IDS.CONTAINER}
                style={{ margin: "0 20px" }}
            >
                <TableActions isLoading={this.state.packageFetchingDone} />
                <Table stripeRows>
                    <Table.Head>
                        <Table.HeadCell
                            {...this.generateHederCellProps("APP_NAME")}
                        >
                            {MESSAGES.PACKAGES_TABLE.COLUMN_NAMES.APP}
                        </Table.HeadCell>
                        <Table.HeadCell width={180}>
                            {MESSAGES.PACKAGES_TABLE.COLUMN_NAMES.STATUS}
                        </Table.HeadCell>
                        <Table.HeadCell width={280}>
                            {MESSAGES.PACKAGES_TABLE.COLUMN_NAMES.ACTIONS}
                        </Table.HeadCell>
                        <Table.HeadCell
                            {...this.generateHederCellProps("UPLOAD_TIME")}
                            width={240}
                        >
                            {
                                MESSAGES.PACKAGES_TABLE.COLUMN_NAMES
                                    .DATE_SUBMITTED
                            }
                        </Table.HeadCell>
                        <Table.HeadCell
                            {...this.generateHederCellProps("VERSION")}
                            width={150}
                        >
                            {MESSAGES.PACKAGES_TABLE.COLUMN_NAMES.VERSION}
                        </Table.HeadCell>
                    </Table.Head>

                    <Table.Body>
                        {packages.length > 0 &&
                            packages.map((row) => (
                                <Table.Row
                                    data-row-id={row.name}
                                    key={row.id}
                                    data-test-name={TEST_IDS.ROW}
                                >
                                    <Table.Cell
                                        data-test-name={TEST_IDS.CELL_NAME}
                                    >
                                        {row.name}
                                    </Table.Cell>
                                    <Table.Cell
                                        data-test-name={TEST_IDS.CELL_STATUS}
                                    >
                                        {this.getPackageStatusComp(row)}
                                    </Table.Cell>
                                    <Table.Cell
                                        data-test-name={TEST_IDS.CELL_ACTIONS}
                                    >
                                        {this.getActionsComp(row)}
                                    </Table.Cell>
                                    <Table.Cell
                                        data-test-name={TEST_IDS.CELL_SUBMITTED}
                                    >
                                        {formatDateIfEpoch(row.submittedDate)}
                                    </Table.Cell>
                                    <Table.Cell
                                        data-test-name={TEST_IDS.CELL_VERSION}
                                    >
                                        {row.version}
                                    </Table.Cell>
                                </Table.Row>
                            ))}
                    </Table.Body>
                </Table>
                {packages.length === 0 && (
                    <div className="table-flashmessages">
                        <div className="alert alert-info">
                            <i className="icon-alert" />
                            {MESSAGES.PACKAGES_TABLE.NO_APPS_ALERT}
                        </div>
                    </div>
                )}
                <CheckAppStatus
                    app={this.checkStatusForPackage}
                    open={this.state.openCheckAppStatusModal}
                    onSuccess={this.handleCheckAppStatusSuccess}
                    handleClose={this.hideCheckAppStatusModal}
                    performActionAfterAuth={this.performActionAfterAuth}
                />
            </div>
        );
    }
}

PackagesTable.propTypes = {
    handleDeleteModalOpen: PropTypes.func.isRequired,
    handleInstallModalOpen: PropTypes.func.isRequired,
    handleMoreInfoModalOpen: PropTypes.func.isRequired,
    handleUpdateModalOpen: PropTypes.func.isRequired,
    packageService: PropTypes.any,
};

export default withPackageService(PackagesTable);
