import { convertJSONToFormEncodedData, parseError } from "@shared/lib/utils";
import {
    defaultFetchInit,
    handleError,
    handleResponse,
} from "@splunk/splunk-utils/fetch";

import AppModel from "@uploadedApps/hoc/PackageServiceHOC/AppModel";
import { LAST_DEPLOY } from "@shared/services/APIService";
import { INSTANCE_TYPES, SORT_DIR } from "@shared/constants";
import { TABLE_HEADER } from "@uploadedApps/UploadedAppsPage/PackagesTable/PackagesTable.constants";
import { _ } from "@splunk/ui-utils/i18n";
import { createRESTURL } from "@splunk/splunk-utils/url";
import { get } from "lodash";
import { getInstanceType } from "@uploadedApps/utils";
import querystring from "querystring";

export const PACKAGES_COLLECTION_PATH = createRESTURL("dmc/packages-paginate");

const NOAH_API_PREFIX = "uploaded-apps/package";
const OUTPUT_MODE_JSON_QS = "?output_mode=json";

const createURLForNoah = (...pathVars) => {
    return createRESTURL(
        [
            NOAH_API_PREFIX,
            pathVars.length ? "/" : "",
            pathVars.join("/"),
            OUTPUT_MODE_JSON_QS,
        ].join("")
    );
};

const urlMap = {
    [INSTANCE_TYPES.DMC]: {
        fetchPackages: PACKAGES_COLLECTION_PATH,
        upload: createRESTURL("dmc/packages-upload"),
    },
    [INSTANCE_TYPES.NOAH]: {
        fetchPackages: createURLForNoah(),
        upload: "/en-US/manager/appinstall/package_upload?output_mode=json",
    },
};

const getEndpoint = (endpoint) => {
    const instanceType = getInstanceType();
    if (!(instanceType in urlMap) || !(endpoint in urlMap[instanceType])) {
        return "";
    }
    return urlMap[instanceType][endpoint];
};

export function acknowledgeRisk(appUniqueId) {
    const accept = true;
    const data = { accept };
    const { headers } = defaultFetchInit;
    const fetchInit = {
        ...defaultFetchInit,
        method: "POST",
        body: JSON.stringify(data),
        headers: {
            ...headers,
            "Content-Type": "application/json",
        },
    };
    const url = createRESTURL(
        `dmc/packages/${encodeURIComponent(appUniqueId)}/ack`
    );
    return fetch(url, fetchInit)
        .then(handleResponse(200))
        .catch(
            handleError(_(`Failed - Acknowledge risk. ID - ${appUniqueId}`))
        );
}

