export function installPackage({ appId, targetedAppInstall }) {
    const { headers } = defaultFetchInit;

    // Default value for DMC
    let url = createRESTURL(`dmc/packages/${appId}/install`);
    let body = JSON.stringify({});
    let contentType = "application/json";
    if (getInstanceType() === INSTANCE_TYPES.NOAH) {
        url = `${createURLForNoah(appId)}${
            targetedAppInstall ? "&scope=local" : ""
        }`;
        body = convertJSONToFormEncodedData({
            _action: "install",
        });
        contentType = "application/x-www-form-urlencoded";
    }
    return fetch(url, {
        body,
        headers: {
            ...headers,
            "Content-Type": contentType,
        },
        method: "POST",
    })
        .then(handleResponse(200))
        .catch(handleError(_(`Unable to install package. - ${appId}`)));
}

export function uploadPackage(file, authToken) {
    const headers = {
        ...defaultFetchInit.headers,
    };
    // Allow browser to determine multipart/form-data headers
    delete headers["Content-Type"];
    let errorHandler = handleError(_(`Unable to upload package`));
    const formData = new FormData();
    if (getInstanceType() === INSTANCE_TYPES.DMC) {
        formData.append("data", file);
        formData.append("token", authToken);
    } else if (getInstanceType() === INSTANCE_TYPES.NOAH) {
        formData.append("upload-app-file", file);
        formData.append("auth_token", authToken);
        errorHandler = parseError;
    }

    return fetch(getEndpoint("upload"), {
        ...defaultFetchInit,
        headers,
        body: formData,
        method: "POST",
    })
        .then(handleResponse(200))
        .then((resp) => {
            if (getInstanceType() === INSTANCE_TYPES.DMC) {
                return {
                    appUniqueId: get(resp, "entry[0].name"),
                };
            }
            return {
                appUniqueId: get(resp, "entry[0].content.app_sha"),
                authToken: get(resp, "entry[0].content.auth_token"),
            };
        })
        .catch(errorHandler);
}

export function deletePackage(appUniqueId) {
    // Default value for DMC
    const url =
        getInstanceType() === INSTANCE_TYPES.DMC
            ? createRESTURL(`dmc/packages/${appUniqueId}`)
            : createURLForNoah(appUniqueId);

    return fetch(url, {
        ...defaultFetchInit,
        method: "DELETE",
    })
        .then(handleResponse(200))
        .catch(handleError(_(`Failed to delete package. ID - ${appUniqueId}`)));
}

export const loginToNoah = ({ username, password }) => {
    const { headers } = defaultFetchInit;

    return fetch(createURLForNoah(), {
        method: "POST",
        body: convertJSONToFormEncodedData({
            _action: "login",
            username,
            password,
        }),
        headers,
    })
        .then(handleResponse(200))
        .then((resp) => get(resp, "entry[0].content.auth_token"))
        .catch(parseError);
};

export const fetchAppVettingStatusRaw = ({ appSHA, authToken }) => {
    const { headers } = defaultFetchInit;

    return fetch(createURLForNoah(appSHA), {
        method: "POST",
        body: convertJSONToFormEncodedData({
            _action: "status",
            auth_token: authToken,
        }),
        headers: {
            ...headers,
        },
    })
        .then(handleResponse(200))
        .catch(parseError);
};

export const fetchAppVettingStatus = ({ appSHA, authToken }) => {
    return fetchAppVettingStatusRaw({ appSHA, authToken }).then(
        (resp) => new AppModel(get(resp, "entry[0]"))
    );
};

