export const isDMCGetPackageEndpointAvailable = async () => {
    try {
        const apiResponseRaw = await fetch(
            createRESTURL(
                "properties/dmc_agent/dmc/get_package_by_id_endpoint_disabled"
            ),
            {
                ...defaultFetchInit,
            }
        );
        return !(await handleResponse(200)(apiResponseRaw));
    } catch (error) {
        return false;
    }
};
