import React from "react";
import PropTypes from "prop-types";
import Paginator from "@splunk/react-ui/Paginator";
import Select from "@splunk/react-ui/Select";
import WaitSpinner from "@splunk/react-ui/WaitSpinner";
import withPackageService from "@uploadedApps/hoc/PackageServiceHOC";
import MESSAGES from "@uploadedApps/messages";
import TEST_IDS from "./TableActions.testids";

class TableActions extends React.Component {
    state = {
        pagination: {
            offset: 0,
            count: 10,
        },
    };

    renderPackagesCount = () => {
        return this.props.isLoading ? (
            MESSAGES.UPLOAD_APPS_PAGE.PACKAGE_COUNT(
                this.props.packageService.totalCount
            )
        ) : (
            <>
                <WaitSpinner
                    style={{ marginRight: "10px" }}
                    data-test-name={TEST_IDS.FETCHING_PACKAGES_SPINNER}
                />
                {MESSAGES.COMMON.LOADING}
            </>
        );
    };

    renderCountSelecter = () => {
        return (
            <Select
                data-test-name={TEST_IDS.PAGE_COUNT_SELECTOR}
                appearance="pill"
                value={this.state.pagination.count}
                onChange={this.handleCountPerPageChange}
            >
                {[10, 25, 50, 100].map((countPerPage) => (
                    <Select.Option
                        key={`${countPerPage}-rows`}
                        label={MESSAGES.UPLOAD_APPS_PAGE.PAGE_COUNT(
                            countPerPage
                        )}
                        value={countPerPage}
                    />
                ))}
            </Select>
        );
    };

    renderPaginator = () => {
        const totalPages = this.calculateTotalPages();
        if (totalPages <= 1) {
            return null;
        }
        return (
            <Paginator
                alwaysShowLastPageLink
                onChange={this.handlePageChange}
                current={
                    this.state.pagination.offset === 0
                        ? 1
                        : this.state.pagination.offset /
                              this.state.pagination.count +
                          1
                }
                totalPages={totalPages}
                data-test-name={TEST_IDS.PAGINATOR}
            />
        );
    };

    handleCountPerPageChange = (e, { value }) => {
        this.setState(
            {
                pagination: {
                    count: value,
                    offset: 0,
                },
            },
            () => {
                this.props.packageService.refreshPackageListing({
                    pagination: this.state.pagination,
                });
            }
        );
    };

    handlePageChange = (event, { page }) => {
        this.setState(
            (prevState) => ({
                pagination: {
                    count: prevState.pagination.count,
                    offset: prevState.pagination.count * (page - 1),
                },
            }),
            () => {
                this.props.packageService.refreshPackageListing({
                    pagination: this.state.pagination,
                });
            }
        );
    };

    calculateTotalPages = () => {
        return this.props.packageService.totalCount > 0
            ? Math.ceil(
                  this.props.packageService.totalCount /
                      this.state.pagination.count
              )
            : 0;
    };

    render() {
        return (
            <div
                style={{
                    display: "flex",
                    flexDirection: "column",
                    marginBottom: 10,
                }}
                data-test-name={TEST_IDS.CONTAINER}
            >
                <div
                    style={{
                        display: "flex",
                        justifyContent: " space-between",
                        marginTop: 10,
                    }}
                >
                    <div
                        style={{
                            display: "flex",
                            alignItems: "center",
                        }}
                    >
                        <div
                            style={{ width: "100px" }}
                            data-test-name={TEST_IDS.TOTAL_PACKAGES_COUNT}
                        >
                            {this.renderPackagesCount()}
                        </div>
                    </div>
                    <div
                        style={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "flex-end",
                        }}
                    >
                        {this.renderCountSelecter()}
                    </div>
                </div>
                <div
                    style={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "flex-end",
                        marginTop: 10,
                    }}
                >
                    {this.renderPaginator()}
                </div>
            </div>
        );
    }
}

TableActions.propTypes = {
    isLoading: PropTypes.bool.isRequired,
    packageService: PropTypes.any,
};

export default withPackageService(TableActions);
