import { getCookieValue } from "@shared/lib/utils";

// Defining a package as a plain objet instead of a Map for ease of serialization.
let packages = {};
let defaultAuthToken = "";
let sessionCookieValue = "";

// Once a user logs in to Splunk, the auth token is saved in this cookie.
const SESSION_COOKIE_KEY = "token_key";
// The namespace used while saving Package Credentials in the sessionStorage
const STORAGE_KEY = "uploaded-apps:package-credentials-store";

const updateTempStorage = () => {
    sessionStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({
            packages,
            defaultAuthToken,
            sessionCookieValue,
        })
    );
};

// Keeps mapping of the packages to the authToken,for retrieving the app vetting status.
class PackageCredentialsStore {
    has = (packageId) => {
        return packageId in packages;
    };

    get = (packageId) => {
        return packages[packageId];
    };

    set = (packageId, data) => {
        if (!defaultAuthToken) {
            defaultAuthToken = data.authToken;
        }
        packages[packageId] = data;
        updateTempStorage();
    };

    getDefaultAuthToken = () => {
        return defaultAuthToken;
    };

    delete = (packageId) => {
        delete packages[packageId];
    };
}

const initializeStore = () => {
    const currSessionCookieValue = getCookieValue(SESSION_COOKIE_KEY);
    // If sessionCookieValue doesn't exist, means either the user isn't logged in OR we are piggy backing on the wrong cookie.
    // This can also happen if the upstream team decided to change the Cookie key to a new key.
    if (!currSessionCookieValue) {
        return;
    }
    sessionCookieValue = currSessionCookieValue;
    const lastSavedValuesStr = sessionStorage.getItem(STORAGE_KEY);
    if (!lastSavedValuesStr) {
        return;
    }
    try {
        const lastSavedValues = JSON.parse(lastSavedValuesStr);
        // If the session cookie value has changed, it implies a new login.
        if (lastSavedValues.sessionCookieValue !== currSessionCookieValue) {
            sessionStorage.removeItem(STORAGE_KEY);
            return;
        }
        packages = lastSavedValues.packages || {};
        defaultAuthToken = lastSavedValues.defaultAuthToken || "";
    } catch (error) {
        console.error(`Error parsing sessionStorage key value`);
    }
};

initializeStore();

export default new PackageCredentialsStore();
