import React from "react";
import Link from "@splunk/react-ui/Link";
import { _ } from "@splunk/ui-utils/i18n";
import { sprintf } from "@splunk/ui-utils/format";
import { isPlainObject, get } from "lodash";

export function isSHC(json) {
    return !!(json.entry?.[0]?.content && json.entry[0].content.SHCDeployer);
}

export function isDMCEnabled(json) {
    return !!(
        json.entry?.[0] &&
        json.entry[0].content &&
        !json.entry[0].content.disabled
    );
}

export function isCloudInstance(serverInfo) {
    return serverInfo?.entry?.[0]?.content?.instance_type === "cloud";
}

export const noop = () => {};

/**
 * Modifies the testIds by prefixing with Remote App Name & compName
 * @param {Object} param Param object
 * @param {string} param.remoteAppName Remote App Name
 * @param {string} param.compName Component Name
 * @param {Object} param.testIds Map of Test Ids
 */
export const prefixDataTestIds = ({
    remoteAppName = "",
    compName = "",
    testIds,
}) => {
    if (typeof testIds !== "object") {
        return {};
    }

    for (const key of Object.keys(testIds)) {
        // eslint-disable-next-line no-param-reassign
        testIds[key] = [remoteAppName, compName, testIds[key]]
            .concat()
            .join("-");
    }
    return testIds;
};

export const isValidDate = (d) => d instanceof Date && !Number.isNaN(d);

export const formatDate = (date) => {
    if (typeof date !== "number") {
        return "-";
    }
    return new Date(date * 1000).toLocaleString();
};

/**
 * If the date provided as a parameter is a string, it return the date as is (i.e. typeof date === string).
 * If the date provided as a paramter is a number(epoch), it uses an already exisitng formatDate function
 * to convert the epoch time to human readable datetime format. formatDateIfEpoch differs from the formatDate
 * becuase of the legacy dependency on formatDate, possibly by other code in the repo.
 * @param {*} date
 * @returns {string} date
 */
export const formatDateIfEpoch = (date) => {
    if (typeof date !== "number") {
        return date;
    }
    return formatDate(date);
};

/**
 * Converts JSON data into url form encoded data.
 * E.g., input - { role: "admin", token: "some token" }
 * output - "role=admin&token=some%20token"
 * @param {Object} data JSON data
 * @returns {String} Returns the url form encoded data
 */
export const convertJSONToFormEncodedData = (data) => {
    if (!isPlainObject(data)) {
        return "";
    }
    return Object.entries(data).reduce((acc, [key, value], index) => {
        const keyValuePair = `${key}=${encodeURIComponent(value)}`;
        return `${acc}${index !== 0 ? "&" : ""}${keyValuePair}`;
    }, "");
};

/**
 * Returns the cookie value, if present.
 * @param {String} cookieName The name of the cookie
 */
export const getCookieValue = (cookieName) => {
    if (!document.cookie) {
        return undefined;
    }
    const cookies = document.cookie.split("; ");
    let result;
    for (const cookie of Object.values(cookies)) {
        const [key, value] = cookie.split("=");
        if (key === cookieName) {
            result = value;
            break;
        }
    }
    return result;
};

const wasPopUpBlocked = (newWin) => {
    return !newWin || newWin.closed || typeof newWin.closed === "undefined";
};

export const renderContentInNewWindow = (content) => {
    if (!content) {
        return null;
    }
    const newTab = window.open();
    if (wasPopUpBlocked(newTab)) {
        // eslint-disable-next-line no-alert
        alert(_("Please make sure the pop-blocker is disabled and try again."));
        return null;
    }
    newTab.document.write(content);
    return newTab;
};

export const getComponentDisplayName = (WrappedComponent) => {
    return WrappedComponent.displayName || WrappedComponent.name || "Component";
};

export const parseError = async (res) => {
    try {
        const error = await res.json();
        if (Array.isArray(error.messages) && error.messages.length) {
            return Promise.reject(
                get(error, "messages[0].text", "GENERIC_ERROR_MESSAGE")
            );
        }
        return Promise.reject(error);
    } catch (e) {
        return Promise.reject(new Error("GENERIC_ERROR_MESSAGE"));
    }
};

export const TARGETED_APP_INSTALL_DOC_URL =
    "https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.2.2510/manage-apps-and-add-ons-in-splunk-cloud-platform/targeted-app-installation-on-victoria-experience";

export const getTargetedAppInstallMessage = (serverInfo, isPrivate = false) => {
    const serverName = serverInfo?.entry?.[0]?.content?.serverName;
    const appType = isPrivate ? "Private" : "Splunk";
    const messageText = sprintf(
        _(
            "%(appType)s app installation is now local to searchheads. You are no longer installing the application on the whole stack, just this %(serverName)s."
        ),
        { appType, serverName }
    );
    return React.createElement(
        React.Fragment,
        null,
        messageText,
        " ",
        React.createElement(
            Link,
            { to: TARGETED_APP_INSTALL_DOC_URL, openInNewContext: true },
            _("Read more about this")
        )
    );
};

export const isAuthenticated = (authToken) => {
    if (!authToken) {
        return false;
    }

    const { value, expiry } = authToken;
    if (!value || !expiry) {
        return false;
    }

    return Date.now() < expiry;
};
