import PollSplunkEndpoint from "./Polling";
import { LAST_DEPLOY } from "./APIService";

let deployPoll;
let latestPollPromise;

const setupDeployPoll = (pollingOptions) => {
    const latestDeployPollingOpt = {
        interval: 5000, // 5 sec
        timeout: 0, // Poll indefinitely
        url: LAST_DEPLOY,
        ...pollingOptions,
    };
    return new PollSplunkEndpoint(latestDeployPollingOpt);
};

class PollDeployService {
    start = (pollingOptions = {}) => {
        if (!deployPoll) {
            deployPoll = setupDeployPoll(pollingOptions);
        }
        if (deployPoll.isPolling) {
            return latestPollPromise;
        }
        latestPollPromise = deployPoll.startPolling();
        return latestPollPromise;
    };

    stop = () => {
        if (!deployPoll || !deployPoll.isPolling) {
            return;
        }
        deployPoll.stopPolling();
    };
}

const PollDeploy = new PollDeployService();
export default PollDeploy;
