import PropTypes from "prop-types";
import React from "react";
import LoginModal from "@shared/components/LoginModal";
import CheckInstallationStatus from "@shared/components/CheckInstallationStatus";
import AcknowledgementModal from "@uploadedApps/UploadedAppsPage/AcknowledgementModal";
import DeleteModal from "@uploadedApps/UploadedAppsPage/DeleteModal";
import AppActionModal, {
    APP_ACTION_MODAL_ACTIONS,
    APP_ACTION_MODAL_STATUSES,
} from "@shared/components/AppActionModal";
import MoreInfoModal from "@uploadedApps/UploadedAppsPage/MoreInfoModal";
import UploadModal from "@uploadedApps/UploadedAppsPage/UploadModal";
import PackagesTable from "@uploadedApps/UploadedAppsPage/PackagesTable";
import VettingProgressModal from "@uploadedApps/UploadedAppsPage/VettingProgressModal";
import VettingErrorModal from "@uploadedApps/UploadedAppsPage/VettingErrorModal";
import { getInstanceType } from "@uploadedApps/utils";
import { get } from "lodash";
import TEST_IDS from "./UploadedAppsPage.testids";
import PageHeader from "./PageHeader";

const UploadedAppsPage = (props) => {
    const supportedDeployments = get(
        props.currentPackage?.raw,
        "content.@manifest.supported_deployments",
        []
    );

    return (
        <div data-test-name={TEST_IDS.CONTAINER}>
            <PageHeader onUploadBtnClick={props.handleUploadBtnClick} />
            <PackagesTable
                handleDeleteModalOpen={props.handleDeleteModalOpen}
                handleInstallModalOpen={props.handleInstallModalOpen}
                handleMoreInfoModalOpen={props.handleMoreInfoModalOpen}
                handleUpdateModalOpen={props.handleUpdateModalOpen}
            />
            {/* App Installation Flow */}
            {props.installUpdateModalConfig?.isOpen && (
                <AppActionModal
                    action={props.installUpdateModalConfig.action}
                    status={props.installUpdateModalConfig.status}
                    appName={props.installUpdateModalConfig.appName}
                    supportedDeployments={supportedDeployments}
                    onConfirm={props.installUpdateModalConfig.handleConfirm}
                    onClose={props.handleModalClose}
                    isWorking={props.installUpdateModalConfig.isWorking}
                    onFinish={props.installUpdateModalConfig.handleFinish}
                    open={props.installUpdateModalConfig.isOpen}
                    errorMessage={props.installUpdateModalConfig.errorMessage}
                />
            )}
            {props.checkInstallationStatusModalConfig?.isOpen ? (
                <CheckInstallationStatus
                    isOpen={props.checkInstallationStatusModalConfig.isOpen}
                    onClose={props.handleModalClose}
                    appId={props.checkInstallationStatusModalConfig.appId}
                />
            ) : null}
            {/*  Upload App Flow */}
            {props.openLoginModal && (
                <LoginModal
                    handleClose={props.handleModalClose}
                    onSuccess={props.handleLoginModalSuccess}
                    open={props.openLoginModal}
                    instanceType={getInstanceType()}
                    action="UPLOAD"
                />
            )}
            {props.openUploadModal && (
                <UploadModal
                    authToken={props.authToken}
                    handleClose={props.handleModalClose}
                    open={props.openUploadModal}
                    onSuccess={props.handleUploadSuccess}
                />
            )}
            {props.openVettingProgressModal && (
                <VettingProgressModal
                    filename={props.filename}
                    open={props.openVettingProgressModal}
                    handleClose={props.handleModalClose}
                />
            )}
            {props.openVettingErrorModal && (
                <VettingErrorModal
                    authToken={props.authToken}
                    handleClose={props.handleModalClose}
                    open={props.openVettingErrorModal}
                    vettingErrorCount={props.vettingErrorCount}
                    app={props.currentPackage}
                />
            )}
            {/* Other modals */}
            {props.openDeleteModal && (
                <DeleteModal
                    app={props.currentPackage}
                    handleClose={props.handleModalClose}
                    open={props.openDeleteModal}
                    onSuccess={props.handleDeleteSuccess}
                />
            )}
            {props.openMoreInfoModal && (
                <MoreInfoModal
                    app={props.currentPackage}
                    handleClose={props.handleModalClose}
                    open={props.openMoreInfoModal}
                />
            )}
            {props.openAcknowledgementModal && (
                <AcknowledgementModal
                    handleClose={props.handleModalClose}
                    open={props.openAcknowledgementModal}
                    app={props.currentPackage}
                    onSuccess={props.handleAckSuccess}
                />
            )}
        </div>
    );
};

UploadedAppsPage.propTypes = {
    authToken: PropTypes.shape({
        value: PropTypes.string.isRequired,
        expiry: PropTypes.number.isRequired,
    }),
    currentPackage: PropTypes.shape({
        name: PropTypes.string.isRequired,
        raw: PropTypes.object,
    }),
    filename: PropTypes.string.isRequired,
    handleDeleteModalOpen: PropTypes.func.isRequired,
    handleInstallModalOpen: PropTypes.func.isRequired,
    handleLoginModalSuccess: PropTypes.func.isRequired,
    handleModalClose: PropTypes.func.isRequired,
    handleMoreInfoModalOpen: PropTypes.func.isRequired,
    handleUpdateModalOpen: PropTypes.func.isRequired,
    handleUploadBtnClick: PropTypes.func.isRequired,
    handleUploadSuccess: PropTypes.func,
    handleDeleteSuccess: PropTypes.func,
    handleAckSuccess: PropTypes.func,
    openAcknowledgementModal: PropTypes.bool.isRequired,
    openDeleteModal: PropTypes.bool.isRequired,
    openLoginModal: PropTypes.bool.isRequired,
    openMoreInfoModal: PropTypes.bool.isRequired,
    openUploadModal: PropTypes.bool.isRequired,
    openVettingErrorModal: PropTypes.bool.isRequired,
    openVettingProgressModal: PropTypes.bool.isRequired,
    vettingErrorCount: PropTypes.number.isRequired,
    checkInstallationStatusModalConfig: PropTypes.shape({
        isOpen: PropTypes.bool.isRequired,
        appId: PropTypes.string.isRequired,
    }),
    installUpdateModalConfig: PropTypes.shape({
        action: PropTypes.oneOf(Object.values(APP_ACTION_MODAL_ACTIONS))
            .isRequired,
        status: PropTypes.oneOf(Object.values(APP_ACTION_MODAL_STATUSES))
            .isRequired,
        appName: PropTypes.string.isRequired,
        handleConfirm: PropTypes.func,
        isOpen: PropTypes.bool.isRequired,
        isWorking: PropTypes.bool.isRequired,
        handleFinish: PropTypes.func,
        errorMessage: PropTypes.string,
    }),
};
export default UploadedAppsPage;
