import { SplunkRum } from "@splunk/otel-web";

/**
 * Splunk RUM initialization for the Admin UI remotes.
 *
 * Every CI job that produces a JS bundle bakes a realm + RUM access token
 * into that bundle via webpack's DefinePlugin (process.env.SPLUNK_RUM_*).
 * Each job in .gitlab-ci.yml exports the values it wants:
 *
 *   - SaaS deploys (deploy:app:preview / playground / staging / production):
 *     one bundle per environment, each environment uses its own token.
 *
 *   - Artifactory release (release:upload-to-test-artifactory and
 *     release:upload-to-artifactory): one tarball is consumed by many
 *     independent Splunk Enterprise / on-prem deployments. By design they
 *     all share a single token so their telemetry lands in one multi-tenant
 *     RUM realm we operate. The test job uses SPLUNK_RUM_DEV; the on-tag
 *     production job uses SPLUNK_RUM_PRODUCTION.
 *
 * In addition to the build-time defaults, the wrapper reads an optional
 * runtime override from window.$C.SPLUNK_RUM. Anything set there overrides
 * (and merges with) the baked-in values. Use this if a host needs to
 * disable RUM (`enabled: false`) or remap to a different realm/token.
 *
 * If neither path supplies a realm and rumAccessToken, the wrapper is a
 * silent no-op: SplunkRum.init is never called, no listeners attach, no
 * spans buffer, and no network calls are made.
 */

let isInitialized = false;

const getRuntimeConfig = () => {
    if (typeof window === "undefined" || !window.$C) {
        return {};
    }

    return window.$C.SPLUNK_RUM || {};
};

export const SplunkOtelWrapper = () => {
    const { packageVersion, appNameDescription } = process.env;
    const nodeEnv = process.env.NODE_ENV;
    const deploymentEnvironment = process.env.SSC_ENV || "development";
    const isTest = nodeEnv === "test" || nodeEnv === "testing";
    const { enabled, ...runtimeConfig } = getRuntimeConfig();

    if (isTest || isInitialized || enabled === false) {
        return;
    }

    const buildDefaults = {
        realm: process.env.SPLUNK_RUM_REALM || undefined,
        rumAccessToken: process.env.SPLUNK_RUM_TOKEN || undefined,
    };

    const rumConfig = {
        ...buildDefaults,
        applicationName: `AdminUI/${appNameDescription}`,
        version: process.env.SPLUNK_RUM_APP_VERSION || packageVersion,
        deploymentEnvironment,
        ...runtimeConfig,
        user: {
            trackingMode: "noTracking",
            ...(runtimeConfig.user || {}),
        },
    };

    if (!rumConfig.realm || !rumConfig.rumAccessToken) {
        return;
    }

    SplunkRum.init(rumConfig);
    isInitialized = true;
};
