const metadata = {};

class GlobalContextStore {
    set = (key, value) => {
        metadata[key] = value;
    };

    setMultiple = (args = {}) => {
        Object.entries(args).forEach(([key, value]) => {
            metadata[key] = value;
        });
    };

    get = (key) => metadata[key];

    delete = (key) => {
        delete metadata[key];
    };
}

export default new GlobalContextStore();

