import { _ } from "@splunk/ui-utils/i18n";
import PropTypes from "prop-types";
import React from "react";
import Button from "@splunk/react-ui/Button";
import Message from "@shared/components/Message";
import Modal from "@splunk/react-ui/Modal";
import { isNil } from "lodash";

import MESSAGES from "@uploadedApps/messages";
import { deletePackage } from "@uploadedApps/services/APIService";
import { MODAL_STATUS } from "@uploadedApps/constants";
import TEST_IDS from "./DeleteModal.testids";

const TITLES = {
    warning: MESSAGES.DELETE_MODAL.MODAL_TITLE_WARNING,
    success: MESSAGES.DELETE_MODAL.MODAL_TITLE_SUCCESS,
    error: MESSAGES.DELETE_MODAL.MODAL_TITLE_ERROR,
};

/**
 * @param {Object} status - status of the modal
 * @param {Object} pkg - Splunk REST response obj
 * @returns {String} - Formatted string to be used in Modal Body
 */
export const getFormattedAppName = (pkg) => {
    const appName = pkg.name;
    const { version } = pkg;
    const { id } = pkg;

    return appName && version
        ? _(`${appName} (version ${version})`)
        : _(`${id}`);
};

const body = {
    warning: MESSAGES.DELETE_MODAL.MODAL_BODY_WARNING,
    success: MESSAGES.DELETE_MODAL.MODAL_BODY_SUCCESS,
    error: MESSAGES.DELETE_MODAL.MODAL_BODY_ERROR,
};

export default class DeleteModal extends React.Component {
    constructor(props) {
        super(props);
        this.state = this.getInitialStateConfig();
    }

    getInitialStateConfig = () => ({
        status: MODAL_STATUS.WARNING,
        isLoading: false,
    });

    handleDeleteBtnClick = async () => {
        if (isNil(this.props, "app.id")) {
            return;
        }
        this.setState({
            isLoading: true,
        });
        try {
            await deletePackage(this.props.app.id);
            this.setState(
                {
                    status: MODAL_STATUS.SUCCESS,
                    isLoading: false,
                },
                () => this.props.onSuccess(this.props.app.id)
            );
        } catch (error) {
            this.setState({
                status: MODAL_STATUS.ERROR,
                isLoading: false,
            });
        }
    };

    handleClose = () => {
        this.setState(
            {
                ...this.getInitialStateConfig(),
            },
            this.props.handleClose
        );
    };

    render() {
        const { open, app } = this.props;
        const { status } = this.state;
        const appName = getFormattedAppName(app);
        const bodyMessage = body[status] ? body[status](appName) : "";

        return (
            <Modal open={open} data-test-name={TEST_IDS.MODAL}>
                <Modal.Header
                    onRequestClose={this.handleClose}
                    title={TITLES[status]}
                />
                <Modal.Body>
                    <Message type={status}>{bodyMessage}</Message>
                </Modal.Body>
                <Modal.Footer>
                    <Button
                        data-test-name={TEST_IDS.CLOSE_BTN}
                        label={MESSAGES.COMMON.CLOSE}
                        onClick={this.handleClose}
                    />
                    {status === MODAL_STATUS.WARNING && (
                        <Button
                            appearance="primary"
                            data-test-name={TEST_IDS.CONTINUE_BTN}
                            label={MESSAGES.COMMON.DELETE}
                            onClick={this.handleDeleteBtnClick}
                            disabled={this.state.isLoading}
                        />
                    )}
                </Modal.Footer>
            </Modal>
        );
    }
}

DeleteModal.propTypes = {
    handleClose: PropTypes.func.isRequired,
    open: PropTypes.bool.isRequired,
    onSuccess: PropTypes.func,
    app: PropTypes.any.isRequired,
};
