import {
    defaultFetchInit,
    handleResponse,
    handleError,
} from "@splunk/splunk-utils/fetch";

import { noop } from "@shared/lib/utils";

class PollSplunkEndpoint {
    constructor(options) {
        this.method = options.method || "GET";
        this.interval = options.interval || 5000;
        this.timeout = options.timeout || 0; // timeout of 0 will poll indefinitely
        this.validationFn = options.validationFn || noop;
        this.pollingInProgress = false;
        this.url = options.url;
        this.timeoutId = undefined;
        this.onEachIteration = options.onEachIteration || noop;
        this.makeRequestFn = options.makeRequestFn;
    }

    makeRequest = () => {
        return this.makeRequestFn
            ? this.makeRequestFn()
            : fetch(this.url, {
                  ...defaultFetchInit,
                  method: this.method,
              })
                  .then(handleResponse(200))
                  .catch(handleError("Could not complete request"));
    };

    get isPolling() {
        return this.pollingInProgress;
    }

    startPolling = async () => {
        this.pollingInProgress = true;
        this.startTime = Date.now(); // Capture the startTime
        const poll = async (resolve, reject) => {
            if (
                this.timeout > 0 &&
                Date.now() - this.startTime > this.timeout
            ) {
                // Reject if timeout period has passed
                this.stopPolling();
                return reject(new Error("Exceeded timeout period"));
            }
            try {
                const result = await this.makeRequest();
                this.onEachIteration(result);
                if (this.validationFn(result)) {
                    this.stopPolling();
                    // Call validation function with REST resp and resolve if true
                    return resolve(result);
                }
                // Continue polling
                this.timeoutId = setTimeout(
                    poll,
                    this.interval,
                    resolve,
                    reject
                );
                return null;
            } catch (error) {
                return reject(error);
            }
        };
        return new Promise(poll);
    };

    stopPolling = () => {
        clearTimeout(this.timeoutId);
        this.pollingInProgress = false;
    };
}

export default PollSplunkEndpoint;
